        function inspectUaePlate(arg0, l2, l3, num, reg) {
            if (typeof arg0 === 'string' && (l2 === undefined || arg0.includes('|'))) {
                const raw = arg0.includes('|') ? arg0.trim() : `${arg0.trim()} | DXB UAE`;
                const uaeMatch = raw.match(/^(.*?)\s*\|\s*([A-Z0-9]{1,3})(?:\s+UAE)?$/i);
                if (uaeMatch) {
                    const mainPart = uaeMatch[1].trim();
                    const regParsed = uaeMatch[2].trim().toUpperCase();
                    const mAuth = mainPart.match(/^([A-ZА-ЯЁ]{1,2}|50|0?[1-9]|1\d|2[0-2])\s+(\d{1,5})$/i);
                    const mLeg3 = mainPart.match(/^([A-ZА-ЯЁ]{3})\s+(\d{1,5})$/i);
                    if (mAuth) {
                        const rawCode = mAuth[1].toUpperCase();
                        const dStr = mAuth[2];
                        const digitsNorm = dStr.length <= 3 ? dStr.padStart(3, '0') : (dStr.replace(/^0+/, '') || dStr);
                        if (/^\d+$/.test(rawCode)) {
                            const catStr = String(parseInt(rawCode, 10) || rawCode);
                            return evaluateUaePlateDetails(catStr, 'X', 'Z', digitsNorm, regParsed);
                        }
                        const p1 = rawCode[0];
                        const isDbl = rawCode.length === 2;
                        return evaluateUaePlateDetails(p1, isDbl ? rawCode[1] : 'X', isDbl ? rawCode[1] : 'Z', digitsNorm, regParsed);
                    }
                    if (mLeg3) {
                        const s3 = mLeg3[1].toUpperCase();
                        const dStr = mLeg3[2];
                        const digitsNorm = dStr.length <= 3 ? dStr.padStart(3, '0') : (dStr.replace(/^0+/, '') || dStr);
                        return evaluateUaePlateDetails(s3[0], s3[1], s3[2], digitsNorm, regParsed);
                    }
                }
            }
            if (arg0 && typeof arg0 === 'object' && !Array.isArray(arg0)) {
                const arr = Array.isArray(arg0.letters) ? arg0.letters : [arg0.l1, arg0.l2, arg0.l3];
                return evaluateUaePlateDetails(arr[0], arr[1], arr[2], arg0.digits ?? arg0.num, arg0.region ?? arg0.reg ?? 'DXB');
            }
            return evaluateUaePlateDetails(arg0, l2, l3, num, reg);
        }
        window.evaluateUaePlateDetails = evaluateUaePlateDetails;
        window.inspectUaePlate = inspectUaePlate;

        function getCalculatedPrice(l1, l2, l3, num, reg, country = currentCountry) {
            const code = String(country || 'RUS').toUpperCase();
            if (code === 'UAE') {
                return evaluateUaePlateDetails(l1, l2, l3, num, reg).price;
            }
            let letters = (l1 || '') + (l2 || '') + (l3 || '');
            const isTripleLetters = (l1 === l2 && l2 === l3);
            const isMirrorLetters = (l1 === l3 && l1 !== l2);
            const isPairLetters = (l1 === l2 || l2 === l3) && !isTripleLetters;
            const specialMeta = getUltraSpecialPlateMeta(l1, l2, l3, num, reg, code);

            if (code !== 'RUS' && PLATE_COUNTRIES[code]) {
                const cfg = PLATE_COUNTRIES[code];
                let price = cfg.basePrice || 600;
                const mult = code === 'JPN' ? 1.85 : (code === 'USA' ? 1.6 : 1.3);
                const cElites = cfg.eliteLetters || [];

                // 1. Престижные серии страны
                if (cElites.includes(letters)) {
                    if (code === 'JPN' && letters === 'JDM' && num === '777') return 24000000;
                    if (code === 'JPN' && letters === 'GTR' && num === '001') return 22000000;
                    if (code === 'USA' && letters === 'VIP' && num === '001') return 16000000;
                    if (code === 'USA' && letters === 'USA' && num === '777') return 14000000;
                    if (code === 'KZ' && letters === 'VIP' && num === '777') return 14000000;
                    if (code === 'KZ' && letters === 'ZZZ' && num === '001') return 12000000;

                    if (num === '777') price += Math.round(5000000 * mult);
                    else if (num[0] === num[1] && num[1] === num[2]) price += Math.round(2000000 * mult);
                    else if (num === '001') price += Math.round(1200000 * mult);
                    else price += Math.round(400000 * mult);

                    if (['VIP', 'USA', 'FBI', 'ZZZ', 'QQQ', 'AAA', 'JDM', 'GTR', 'TKY'].includes(letters)) {
                        price += Math.round(1300000 * mult);
                    } else {
                        price += Math.round(750000 * mult);
                    }
                    if (specialMeta && specialMeta.id === 'jdm_glow') {
                        price += 6500000;
                    }
                }

                // 2. Структура букв
                if (isTripleLetters) price += Math.round(350000 * mult);
                else if (isMirrorLetters) price += Math.round(1800 * mult);
                else if (isPairLetters) price += Math.round(1200 * mult);

                // 3. Комбинации цифр
                if (num[0] === num[1] && num[1] === num[2]) {
                    price += Math.round((num === '777' ? 750000 : 320000) * mult);
                } else if (num === '001') {
                    price += Math.round(350000 * mult);
                } else if (num === '007') {
                    price += Math.round(120000 * mult);
                } else if (num.startsWith('00')) {
                    price += Math.round(35000 * mult);
                } else if (num.endsWith('00')) {
                    price += Math.round(25000 * mult);
                } else if (['123','234','345','456','567','678','789','987','876','765','654','543','432','321'].includes(num)) {
                    price += Math.round(20000 * mult);
                } else if (['010','020','030','040','050','060','070','080','090'].includes(num)) {
                    price += Math.round(2000 * mult);
                } else if (num[0] === num[2]) {
                    price += Math.round(1600 * mult);
                }

                // 4. Престижные регионы / штаты / эмираты / префектуры
                const regStr = String(reg || '').toUpperCase();
                if (
                    (code === 'KZ' && ['01', '02', '77'].includes(regStr)) ||
                    (code === 'USA' && ['CA', 'NY', 'FL', 'NV', 'TX'].includes(regStr)) ||
                    (code === 'JPN' && ['TKY', 'YKH', 'OSK', 'NGY', 'SPR'].includes(regStr))
                ) {
                    price += Math.round(500 * mult);
                    if (num === '777' || num === '001') price += Math.round(500000 * mult);
                    if (isTripleLetters) price += Math.round(60000 * mult);
                }

                return price;
            }

            let price = 450;

            // 0. Ультра-редкие спецномера (СССР ГОСТ, Дипломатический CD, МВД Синий, Военный МО, Федеральный ФСО)
            if (specialMeta) {
                price += 18000000;
                if (num === '001' || num === '777') price += 15000000;
                else if (num === '007' || (num[0] === num[1] && num[1] === num[2])) price += 9000000;
                else if (num.endsWith('00')) price += 4500000;
            }

            // 1. Престижные серии
            if (eliteLetters.includes(letters)) {
                if (letters === 'ЕКХ' && num === '011') return 12000000;
                if (num === '777') price += 5000000;
                else if (num[0] === num[1] && num[1] === num[2]) price += 2000000;
                else if (num === '001') price += 1200000;
                else price += 400000;
            }
            if (letters === 'ЕКХ') price += 1500000;
            if (letters === 'АМР') price += 1500000;
            if (letters === 'ВОР') price += 1000000;
            if (letters === 'ООО') price += 850000;
            if (letters === 'ААА') price += 1200000;
            if (letters === 'МММ') price += 750000;
            if (letters === 'ССС') price += 650000;
            if (letters === 'СКР') price += 700000;
            if (letters === 'УУУ') price += 600000;

            // 2. Структура букв
            if (isTripleLetters) price += 350000;
            else if (isMirrorLetters) price += 1800;
            else if (isPairLetters) price += 1200;

            // 3. Комбинации цифр
            if (num[0] === num[1] && num[1] === num[2]) {
                price += (num === '777' ? 750000 : 320000);
            } else if (num === '001') {
                price += 350000;
            } else if (num === '007') {
                price += 120000;
            } else if (num.startsWith('00')) {
                price += 35000;
            } else if (num.endsWith('00')) {
                price += 25000;
            } else if (['123','234','345','456','567','678','789','987','876','765','654','543','432','321'].includes(num)) {
                price += 20000;
            } else if (['010','020','030','040','050','060','070','080','090'].includes(num)) {
                price += 2000;
            } else if (num[0] === num[2]) {
                price += 1600;
            }

            // 4. Престижные регионы (символическая надбавка + синергия с элитой)
            if (['777','77','99','799','797','СССР','CD'].includes(String(reg || '').toUpperCase())) {
                price += 250;
                if (num === '777') price += 500000;
                if (isTripleLetters) price += 50000;
            } else if (['78','98','178','198'].includes(reg)) {
                price += 200;
            } else if (reg === '95') {
                price += 200;
            } else if (reg === '16' || reg === '116' || reg === '716') {
                price += 150;
            }

            return price;
        }

        function calculatePrice() {
            return getCalculatedPrice(currentL1, currentL2, currentL3, currentNum, currentReg, currentCountry);
        }

        function calculatePlatePriceForCountry(countryCode, l1, l2, l3, num, reg) {
            const code = String(countryCode || currentCaseCountry || currentCountry || 'RUS').toUpperCase();
            const c = COUNTRY_CONFIGS[code] ? code : 'RUS';
            const r = (reg !== undefined && reg !== null && String(reg).trim() !== '')
                ? String(reg).trim()
                : (COUNTRY_CONFIGS[c].defaultReg || '777');
            return getCalculatedPrice(l1, l2, l3, String(num || '001'), r, c);
        }
        if (typeof window !== 'undefined') {
            window.calculatePlatePriceForCountry = calculatePlatePriceForCountry;
        }

        function getRarity(price) {
            if (price >= 10000000) return { text: "БЛАТНОЙ", color: "white", bg: "linear-gradient(45deg, #e0115f, #ffd700)", border: "1px solid #ffd700", glow: "blatnoy" };
            if (price >= 3000000) return { text: "Крутой", color: "white", bg: "linear-gradient(45deg, #ff1493, #8a2be2)", border: "1px solid #ff1493", glow: "blatnoy" };
            if (price >= 1000000) return { text: "Легендарный", color: "black", bg: "#f59e0b", border: "1px solid black", glow: "legendary" };
            if (price >= 300000) return { text: "Эпический", color: "white", bg: "#8b5cf6", border: "1px solid black", glow: "epic" };
            if (price >= 80000) return { text: "Супер редкий", color: "white", bg: "#ef4444", border: "1px solid black", glow: "super" };
            if (price >= 18000) return { text: "Редкий", color: "white", bg: "#10b981", border: "1px solid black", glow: "rare" };
            if (price >= 2000) return { text: "Необычный", color: "white", bg: "#3b82f6", border: "1px solid black", glow: "uncommon" };
            return { text: "Обычный", color: "white", bg: "transparent", border: "none", glow: "none" };
        }

        function randomItem(arr) {
            return arr[Math.floor(Math.random() * arr.length)];
        }

        function selectPlateCountry(countryCode) {
            if (isSpinning || serverSpinBusy) return;
            const code = String(countryCode || 'RUS').toUpperCase();
            const cfg = PLATE_COUNTRIES[code];
            if (!cfg) return;
            if(window.NOMERA_AUTHORS_PREVIEW)window.NomeraPrestige?.cancel();
            const prevCountry = currentCountry;
            currentCountry = code;
            currentReg = cfg.defaultReg || cfg.defaultRegion;

            if (code !== prevCountry) {
                boardHasLetters = false;
                boardHasNumbers = false;
                hasSpunLetSinceSave = false;
                hasSpunNumSinceSave = false;
                mustSpinBothForNextSave = false;
                currentL1 = '-';
                currentL2 = '-';
                currentL3 = '-';
                currentNum = '---';
                ['cell-l1', 'cell-l2', 'cell-l3', 'cell-n1', 'cell-n2', 'cell-n3', 'cell-n4', 'cell-n5'].forEach(id => setCellChar(id, '-'));
                if (onlineProfile && onlineProfile.draft && typeof onlineProfile.draft === 'object') {
                    onlineProfile.draft.hasNumbers = false;
                    onlineProfile.draft.hasLetters = false;
                    onlineProfile.draft.changedNumbers = false;
                    onlineProfile.draft.changedLetters = false;
                    onlineProfile.draft.num = '---';
                    onlineProfile.draft.letters = ['-', '-', '-'];
                }
            }

            const regEl = document.getElementById('region');
            if (regEl) regEl.innerText = currentReg;
            const flagEl = document.getElementById('plate-country-flag');
            if (flagEl) {
                if (flagEl.classList) {
                    flagEl.classList.remove('flag-rus', 'flag-kz', 'flag-usa', 'flag-uae', 'flag-jpn');
                    flagEl.classList.add('flag-' + code.toLowerCase());
                } else {
                    flagEl.className = 'flag flag-' + code.toLowerCase();
                }
            }
            const codeEl = document.getElementById('plate-country-code');
            if (codeEl) codeEl.innerText = cfg.code;

            const plateBox = document.getElementById('plate-box');
            if (plateBox) {
                plateBox.classList.remove('country-rus', 'country-kz', 'country-usa', 'country-uae', 'country-jpn');
                plateBox.classList.add('country-' + code.toLowerCase());
            }
            updatePlateBoxMeta(currentCountry, currentReg);

            if (typeof document !== 'undefined' && typeof document.querySelectorAll === 'function') {
                const btns = document.querySelectorAll('.country-select-btn, .country-pill');
                if (btns && typeof btns.forEach === 'function') {
                    btns.forEach(btn => {
                        const btnCountry = btn.getAttribute ? btn.getAttribute('data-country') : (btn.dataset ? btn.dataset.country : '');
                        if (btn.classList) {
                            btn.classList.toggle('active', String(btnCountry).toUpperCase() === code);
                        }
                    });
                }
            }

            const numCostStr = `${cfg.spinCostPart.toLocaleString('ru-RU')} ₽`;
            const bothCostStr = `${cfg.spinCostBoth.toLocaleString('ru-RU')} ₽`;
            ['spin-cost-num', 'spin-num-cost'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.innerText = numCostStr;
            });
            ['spin-cost-let', 'spin-let-cost'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.innerText = numCostStr;
            });
            ['spin-cost-both', 'spin-both-cost'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.innerText = bothCostStr;
            });

            const regLabelEl = document.getElementById('region-editor-label');
            if (regLabelEl) regLabelEl.innerText = cfg.regHint;
            const regInputEl = document.getElementById('region-edit-input');
            if (regInputEl) {
                regInputEl.placeholder = currentReg;
                regInputEl.maxLength = cfg.regMaxLen || 3;
            }
            const chipsBox = document.getElementById('region-quick-chips');
            if (chipsBox && Array.isArray(cfg.popularRegions)) {
                chipsBox.innerHTML = cfg.popularRegions
                    .map(r => `<button type="button" class="region-chip" onclick="saveRegionEdit('${r}')">${r}</button>`)
                    .join('');
            }

            if (onlineProfile) {
                if (onlineProfile.draft && typeof onlineProfile.draft === 'object') {
                    onlineProfile.draft.reg = currentReg;
                    onlineProfile.draft.country = currentCountry;
                }
                onlineRequest('setRegion', { region: currentReg, country: currentCountry }).catch(() => {});
            }

            if (typeof selectCaseCountry === 'function') {
                selectCaseCountry(code, true);
            }

            syncPlateBoxCellsLayout();
            checkCanSaveButton();
            notifyUser(`Выбран стандарт номеров: ${cfg.flagEmoji} ${cfg.name} (${cfg.code})`, 'info');
        }
        if (typeof window !== 'undefined') {
            window.selectPlateCountry = selectPlateCountry;
        }

        function changeRegion() {
            if (isSpinning) return;
            const input = document.getElementById('region-edit-input');
            const editor = document.getElementById('region-editor');
            if (!input || !editor) return;
            input.value = currentReg;
            editor.classList.remove('hidden');
            if (typeof input.focus === 'function') input.focus();
            if (typeof input.select === 'function') input.select();
        }
        function saveRegionEdit(customVal) {
            const input = document.getElementById('region-edit-input');
            const editor = document.getElementById('region-editor');
            const rawNext = String(customVal !== undefined ? customVal : (input ? input.value : '')).trim();
            const cfg = PLATE_COUNTRIES[currentCountry] || PLATE_COUNTRIES.RUS;
            const next = currentCountry === 'RUS' ? rawNext : rawNext.toUpperCase();
            if (currentCountry === 'RUS') {
                if (!/^\d{2,3}$/.test(next)) { notifyUser('Регион должен содержать 2 или 3 цифры', 'error'); return; }
            } else {
                if (!cfg.regionRegex.test(next)) { notifyUser(cfg.regionHint, 'error'); return; }
            }
            currentReg = next;
            const regEl = document.getElementById('region');
            if (regEl) regEl.innerText = currentReg;
            updatePlateBoxMeta(currentCountry, currentReg);
            if (editor) editor.classList.add('hidden');
            if (onlineProfile) {
                if (onlineProfile.draft && typeof onlineProfile.draft === 'object') {
                    onlineProfile.draft.reg = next;
                    if (currentCountry !== 'RUS') onlineProfile.draft.country = currentCountry;
                }
                const payload = currentCountry === 'RUS' ? { region: currentReg } : { region: currentReg, country: currentCountry };
                onlineRequest('setRegion', payload).catch(() => {});
            }
            checkCanSaveButton();
            notifyUser(`Регион изменён: ${currentReg}`, 'success');
        }
        function cancelRegionEdit() {
            document.getElementById('region-editor')?.classList.add('hidden');
        }

        function checkCanSaveButton() {
            let canSaveNow = false;
            if (boardHasLetters && boardHasNumbers) {
                if (mustSpinBothForNextSave) {
                    canSaveNow = (hasSpunLetSinceSave && hasSpunNumSinceSave);
                } else {
                    canSaveNow = (hasSpunLetSinceSave || hasSpunNumSinceSave);
                }
            }

            const btnSave = document.getElementById('btn-save');
            if (btnSave) {
                btnSave.disabled = !canSaveNow;
                if (canSaveNow) btnSave.classList.add('can-save');
                else btnSave.classList.remove('can-save');
            }

            const btnSell = document.getElementById('btn-sell-direct');
            if (btnSell) {
                btnSell.disabled = !canSaveNow;
                if (canSaveNow) {
                    btnSell.classList.add('can-sell');
                    let price = calculatePrice();
                    btnSell.innerHTML = `<span>💰 Продать</span><small>+${price.toLocaleString('ru-RU')} ₽</small>`;
                } else {
                    btnSell.classList.remove('can-sell');
                    btnSell.innerHTML = `<span>💰 Продать</span>`;
                }
            }

            const specialBadgeEl = document.getElementById('special-series-badge');
            const plateDescEl = document.getElementById('current-plate-desc');
            const uaePassportEl = document.getElementById('uae-plate-passport');

            if (boardHasLetters && boardHasNumbers) {
                let price = calculatePrice();
                let rarity = getRarity(price);
                const specialMeta = getUltraSpecialPlateMeta(currentL1, currentL2, currentL3, currentNum, currentReg, currentCountry);
                const cCode = String(currentCountry || 'RUS').toUpperCase();
                const isRoyalRarity = ['БЛАТНОЙ', 'Легендарный', 'Крутой', 'Мифический', 'МИФИЧЕСКИЙ'].includes(rarity.text);
                const isEpicRarity = ['Эпический', 'Супер редкий'].includes(rarity.text);

                if (specialBadgeEl) {
                    specialBadgeEl.innerHTML = specialMeta
                        ? `<div class="special-series-pill" style="display:inline-flex;align-items:center;gap:6px;padding:4px 10px;border-radius:999px;background:rgba(245,158,11,0.16);border:1px solid rgba(245,158,11,0.4);color:#fbbf24;font-weight:800;font-size:11px;margin-bottom:6px;">🏛️ ${escapeHtml(specialMeta.title)}</div>`
                        : '';
                }
                if (plateDescEl) {
                    const descParts = [];
                    if (specialMeta && specialMeta.desc) descParts.push(escapeHtml(specialMeta.desc));
                    descParts.push(`Категория: <b>${escapeHtml(rarity.text)}</b> • Страна: <b>${escapeHtml(cCode)}</b> • Регион/код: <b>${escapeHtml(String(currentReg || ''))}</b>`);
                    plateDescEl.innerHTML = descParts.join('<br>');
                }

                if (cCode === 'UAE') {
                    const uaeInfo = evaluateUaePlateDetails(currentL1, currentL2, currentL3, currentNum, currentReg);
                    document.getElementById('current-price-display').innerHTML = `<span class="price-hero-value" style="white-space:nowrap;">${price.toLocaleString('ru-RU')} ₽</span> <span class="price-sub-aed">≈ ${uaeInfo.estimatedAed.toLocaleString('ru-RU')} AED ($${uaeInfo.estimatedUsd.toLocaleString('ru-RU')})</span>`;
                    if (uaePassportEl) {
                        uaePassportEl.innerHTML = `<div class="price-uae-passport"><b>${escapeHtml(uaeInfo.tierTitle)}</b> · ${escapeHtml(uaeInfo.codePrestige)}<br><span>${escapeHtml(uaeInfo.realWorldNote)}</span></div>`;
                    }
                    let rLabel = document.getElementById('gen-rarity');
                    rLabel.innerText = `${uaeInfo.tierBadge} • ${rarity.text}`;
                    rLabel.style.background = rarity.bg;
                    rLabel.style.color = rarity.color;
                    rLabel.setAttribute('data-rarity-glow', rarity.glow || 'none');
                    rLabel.classList.remove('hidden');
                } else {
                    document.getElementById('current-price-display').innerHTML = `<span class="price-hero-value" style="white-space:nowrap;">${price.toLocaleString('ru-RU')} ₽</span>`;
                    if (uaePassportEl) uaePassportEl.innerHTML = '';
                    let rLabel = document.getElementById('gen-rarity');
                    const baseBadgeText = specialMeta ? `${specialMeta.title} • ${rarity.text}` : rarity.text;
                    rLabel.innerText = isRoyalRarity
                        ? `👑 ${baseBadgeText} 👑`
                        : (isEpicRarity ? `✨ ${baseBadgeText} ✨` : baseBadgeText);
                    rLabel.style.background = rarity.bg;
                    rLabel.style.color = rarity.color;
                    rLabel.setAttribute('data-rarity-glow', rarity.glow || 'none');
                    rLabel.classList.remove('hidden');
                }
                updatePlateGlow(rarity.text);
            } else {
                const priceEl = document.getElementById('current-price-display');
                if (priceEl) {
                    priceEl.innerHTML = `<span class="price-hero-value price-placeholder">— ₽</span>`;
                }
                if (specialBadgeEl) specialBadgeEl.innerHTML = '';
                if (plateDescEl) plateDescEl.innerHTML = 'Сделайте спин, чтобы узнать подробности серии, региона и редкости госномера.';
                if (uaePassportEl) uaePassportEl.innerHTML = '';
                document.getElementById('gen-rarity')?.classList.add('hidden');
                updatePlateGlow('none');
            }
        }

        // --- ДВИЖОК ПРОКРУТКИ ЯЧЕЕК (CELL-BY-CELL REEL ENGINE) ---
        const cellSpanCache = {};
        function getCellSpan(cellId) {
            if (!cellSpanCache[cellId]) {
                const cell = document.getElementById(cellId) || document.getElementById('cell-' + cellId);
                if (cell) {
                    cellSpanCache[cellId] = cell.querySelector('.char-span');
                }
            }
            return cellSpanCache[cellId];
        }

        function setCellChar(cellId, char) {
            const span = getCellSpan(cellId);
            if (span && span.textContent !== char) {
                span.textContent = char;
                span.innerText = char;
            }
        }

        function executeCellSpin(targets, finalValues, onFinish) {
            initAudio();
            if(window.NOMERA_AUTHORS_PREVIEW)window.NomeraPrestige?.cancel();
            isSpinning = true;

            if (String(currentCountry || 'RUS').toUpperCase() === 'UAE' && Array.isArray(targets) && finalValues) {
                const fL1 = (finalValues['cell-l1'] ?? finalValues.l1) ?? currentL1;
                const fL2 = (finalValues['cell-l2'] ?? finalValues.l2) ?? currentL2;
                const fL3 = (finalValues['cell-l3'] ?? finalValues.l3) ?? currentL3;
                const uaeDoubleCode = Boolean(fL1 && fL1 !== '-' && fL1 === fL2 && fL2 === fL3);

                if (finalValues['cell-l3'] !== undefined || finalValues.l3 !== undefined) {
                    setCellChar('cell-l3', fL3);
                }
                if (!uaeDoubleCode && (finalValues['cell-l2'] !== undefined || finalValues.l2 !== undefined)) {
                    setCellChar('cell-l2', fL2);
                }

                const hasNumTargets = targets.some(id => id.startsWith('cell-n'));
                const hasLetTargets = targets.some(id => id.startsWith('cell-l'));
                let nextTargets = [];
                if (hasLetTargets) {
                    nextTargets.push('cell-l1');
                    if (uaeDoubleCode) nextTargets.push('cell-l2');
                }
                if (hasNumTargets) {
                    const cleanDigits = getUaePlateDisplayParts(fL1, fL2, fL3, currentNum).digits;
                    const dLen = Math.min(5, Math.max(1, cleanDigits.length));
                    for (let i = 0; i < 5; i++) {
                        const cId = 'cell-n' + (i + 1);
                        if (i < dLen) {
                            nextTargets.push(cId);
                            finalValues[cId] = cleanDigits[i];
                        } else {
                            setCellChar(cId, '-');
                            const hiddenEl = document.getElementById(cId);
                            if (hiddenEl && hiddenEl.classList) {
                                hiddenEl.classList.remove('spinning', 'stopped');
                            }
                        }
                    }
                }
                if (nextTargets.length > 0) {
                    targets = nextTargets;
                }
            }

            syncPlateBoxCellsLayout();

            const animStyleSelect = document.getElementById('anim-style-select');
            const animStyle = animStyleSelect ? animStyleSelect.value : 'cascade';
            const turboToggle = document.getElementById('turbo-toggle');
            const isTurbo = !!(turboToggle && turboToggle.checked);

            const stopDelays = {};
            const speedScale = isTurbo ? 0.35 : 1.0;

            if (animStyle === 'sync') {
                const syncTime = 600 * speedScale;
                targets.forEach(id => stopDelays[id] = syncTime);
            }
            else if (animStyle === 'suspense') {
                targets.forEach((id, idx) => {
                    if (id.startsWith('cell-l')) stopDelays[id] = (250 + idx * 80) * speedScale;
                    else if (id === 'cell-n1') stopDelays[id] = 550 * speedScale;
                    else if (id === 'cell-n2') stopDelays[id] = 900 * speedScale;
                    else if (id === 'cell-n3') stopDelays[id] = 1600 * speedScale;
                    else if (id === 'cell-n4') stopDelays[id] = 1950 * speedScale;
                    else if (id === 'cell-n5') stopDelays[id] = 2300 * speedScale;
                    else stopDelays[id] = (400 + idx * 100) * speedScale;
                });
            }
            else if (animStyle === 'converge') {
                const total = targets.length;
                targets.forEach((id, idx) => {
                    const distFromEdge = Math.min(idx, total - 1 - idx);
                    stopDelays[id] = (350 + distFromEdge * 350) * speedScale;
                });
            }
            else if (animStyle === 'chaos') {
                const shuffledDelays = targets.map((_, i) => (300 + i * 220) * speedScale);
                for (let i = shuffledDelays.length - 1; i > 0; i--) {
                    const j = Math.floor(Math.random() * (i + 1));
                    [shuffledDelays[i], shuffledDelays[j]] = [shuffledDelays[j], shuffledDelays[i]];
                }
                targets.forEach((id, idx) => stopDelays[id] = shuffledDelays[idx]);
            }
            else if (animStyle === 'wave') {
                targets.forEach((id, idx) => {
                    stopDelays[id] = (window.NOMERA_AUTHORS_PREVIEW ? 320 + Math.abs(idx - (targets.length - 1) / 2) * 150 + (idx % 2) * 70 : 300 + idx * 160) * speedScale;
                });
            }
            else {
                // cascade (default)
                targets.forEach((id, idx) => {
                    stopDelays[id] = (350 + idx * 240) * speedScale;
                });
            }

            const targetElements = {};
            targets.forEach(id => {
                const cellEl = document.getElementById(id);
                if (cellEl) {
                    targetElements[id] = cellEl;
                    cellEl.classList.add('spinning');
                    cellEl.classList.remove('stopped');
                }
            });

            const startTime = performance.now();
            const activeCells = new Set(targets);
            const maxDuration = Math.max(...Object.values(stopDelays)) + 150;
            let lastTickTime = 0;
            let animFrameId = null;

            const requestAnim = (typeof window !== 'undefined' && window.requestAnimationFrame) ? window.requestAnimationFrame.bind(window) : (cb => setTimeout(cb, 16));
            const cancelAnim = (typeof window !== 'undefined' && window.cancelAnimationFrame) ? window.cancelAnimationFrame.bind(window) : (id => clearTimeout(id));

            function finishSpin() {
                if (animFrameId) cancelAnim(animFrameId);
                targets.forEach(id => {
                    const cellEl = targetElements[id] || document.getElementById(id);
                    if (cellEl) cellEl.classList.remove('spinning');
                    setCellChar(id, finalValues[id]);
                });

                isSpinning = false;
                syncPlateCountryDOM(currentCountry, currentReg);
                syncPlateBoxCellsLayout();
                checkCanSaveButton();
                saveProgress();

                if (boardHasLetters && boardHasNumbers) {
                    let finalPrice = calculatePrice();
                    let r = getRarity(finalPrice);
                    flashPlateReward(r.text);
                    const isHighTier = ['Редкий', 'Супер редкий', 'Эпический', 'Легендарный', 'БЛАТНОЙ', 'Крутой', 'Мифический'].includes(r.text);
                    if (isHighTier) {
                        pityCounterBoth = 0;
                        updatePityUI();
                    }
                    if (r.text === "БЛАТНОЙ" || r.text === "Легендарный" || r.text === "Крутой" || r.text === "Мифический") {
                        if(!(window.NOMERA_AUTHORS_PREVIEW&&window.NomeraPrestige)){triggerLegendaryEffect();triggerScreenShake();}
                        playWinJingle(r.text);
                        if (typeof sound?.haptic === 'function') sound.haptic('win');
                    } else if (r.text === "Эпический") {
                        playWinJingle(r.text);
                        if (typeof sound?.haptic === 'function') sound.haptic('win');
                    } else if (r.text === "Редкий") {
                        if (typeof sound?.haptic === 'function') sound.haptic('medium');
                    } else if (r.text === "Супер редкий") {
                        playWinJingle(r.text);
                        if (typeof sound?.haptic === 'function') sound.haptic('win');
                    }
                    const curPlateText = formatPlateText(currentL1, currentL2, currentL3, currentNum, currentReg, currentCountry);
                    logPlayerActivity('Крутит номер', `Выпал госномер «${curPlateText}» (${escapeHtml(r.text)}, ${finalPrice.toLocaleString('ru-RU')} ₽)`);
                    recordQuestProgress('spins', 1);
                    checkAchievements();

                    // Авто-прокрутка: остановка на красных (Супер редкий >= 80 000 ₽), эпических (>= 300 000 ₽) и выше, на остальных автоматом продает
                    if (isAutoSpinning) {
                        const isStopTier = finalPrice >= 80000 || ['Супер редкий', 'Эпический', 'Легендарный', 'Крутой', 'БЛАТНОЙ', 'Мифический'].includes(r.text);
                        if (isStopTier) {
                            // Stop auto-spin on high rarity tier: toggleAutoSpin()
                            stopAutoSpin();
                            notifyUser(`🔥 Выбит ценный номер «${curPlateText}» (${r.text}, ${finalPrice.toLocaleString('ru-RU')} ₽)! Авто-прокрутка остановлена.`, 'success');
                        } else {
                            const turbo = document.getElementById('turbo-toggle');
                            const nextDelay = (turbo && turbo.checked) ? 120 : 450;
                            // Auto-spin auto-sell: sellCurrentPlate()
                            Promise.resolve(sellCurrentPlate(true)).catch(err => {
                                console.warn('Auto-spin auto-sell error:', err);
                            }).finally(() => {
                                if (isAutoSpinning) {
                                    if (autoSpinTimerId) {
                                        clearTimeout(autoSpinTimerId);
                                        autoSpinTimerId = null;
                                    }
                                    autoSpinTimerId = setTimeout(runAutoSpinStep, nextDelay);
                                }
                            });
                        }
                    }
                }

                if (onFinish) onFinish();
            }

            function frameStep(now) {
                const elapsed = now - startTime;

                if (now - lastTickTime >= 48) {
                    lastTickTime = now;
                    playTick();
                    const activeLettersPool = (PLATE_COUNTRIES[currentCountry] && PLATE_COUNTRIES[currentCountry].letters) || lettersArr;
                    const isUaeSpin = String(currentCountry || 'RUS').toUpperCase() === 'UAE';
                    activeCells.forEach(id => {
                        if (id.startsWith('cell-l')) setCellChar(id, randomItem(activeLettersPool));
                        else if (isUaeSpin && id === 'cell-n1') setCellChar(id, (1 + Math.floor(Math.random() * 9)).toString());
                        else setCellChar(id, Math.floor(Math.random() * 10).toString());
                    });
                }

                activeCells.forEach(id => {
                    if (elapsed >= stopDelays[id]) {
                        activeCells.delete(id);
                        const cellEl = targetElements[id] || document.getElementById(id);
                        if (cellEl) {
                            cellEl.classList.remove('spinning');
                            cellEl.classList.add('stopped');
                        }
                        setCellChar(id, finalValues[id]);

                        let pitch = 0.9 + (targets.indexOf(id) * 0.1);
                        playLockSound(pitch);
                        if (typeof sound?.haptic === 'function') sound.haptic('medium');
                    }
                });

                if (activeCells.size === 0 || elapsed > maxDuration) {
                    finishSpin();
                } else {
                    animFrameId = requestAnim(frameStep);
                }
            }

            animFrameId = requestAnim(frameStep);
        }

        // One generator UI. Signed-in players receive a server-authorized number;
        // guest spins stay local and are never sellable on the online market.
        let serverSpinBusy=false;
        function syncServerDraft(draft, mode) {
            if(!draft)return;
            const updateLetters = (mode === 'both' || mode === 'letters' || !mode);
            const updateNumbers = (mode === 'both' || mode === 'numbers' || !mode);

            const resolvedCountry = (draft.country && PLATE_COUNTRIES[String(draft.country).toUpperCase()])
                ? String(draft.country).toUpperCase()
                : inferCountryFromRegion(draft.reg, currentCountry);
            if (PLATE_COUNTRIES[resolvedCountry]) {
                currentCountry = resolvedCountry;
            }

            if (draft.reg) {
                currentReg = String(draft.reg).trim();
            } else if (PLATE_COUNTRIES[currentCountry] && !PLATE_COUNTRIES[currentCountry].regPattern.test(String(currentReg || ''))) {
                currentReg = PLATE_COUNTRIES[currentCountry].defaultReg;
            }

            if (updateLetters) {
                if (draft.hasLetters || mode === 'both' || mode === 'letters') {
                    if (draft.letters && Array.isArray(draft.letters)) {
                        [currentL1, currentL2, currentL3] = draft.letters;
                        if (!mode) {
                            setCellChar('cell-l1', currentL1);
                            setCellChar('cell-l2', currentL2);
                            setCellChar('cell-l3', currentL3);
                        }
                    }
                    boardHasLetters = !!draft.hasLetters;
                    hasSpunLetSinceSave = !!draft.changedLetters;
                } else if (!mode && draft.hasLetters === false) {
                    currentL1 = '-'; currentL2 = '-'; currentL3 = '-';
                    setCellChar('cell-l1', '-');
                    setCellChar('cell-l2', '-');
                    setCellChar('cell-l3', '-');
                    boardHasLetters = false;
                    hasSpunLetSinceSave = false;
                }
            }

            if (updateNumbers) {
                if (draft.hasNumbers || mode === 'both' || mode === 'numbers') {
                    if (draft.num) {
                        currentNum = draft.num;
                        if (!mode && currentCountry !== 'UAE' && currentNum.length === 3) {
                            setCellChar('cell-n1', currentNum[0]);
                            setCellChar('cell-n2', currentNum[1]);
                            setCellChar('cell-n3', currentNum[2]);
                        }
                    }
                    boardHasNumbers = !!draft.hasNumbers;
                    hasSpunNumSinceSave = !!draft.changedNumbers;
                } else if (!mode && draft.hasNumbers === false) {
                    currentNum = '---';
                    ['cell-n1', 'cell-n2', 'cell-n3', 'cell-n4', 'cell-n5'].forEach(id => setCellChar(id, '-'));
                    boardHasNumbers = false;
                    hasSpunNumSinceSave = false;
                }
            }

            syncPlateCountryDOM(currentCountry, currentReg);
            syncPlateBoxCellsLayout();
            mustSpinBothForNextSave = true;
            checkCanSaveButton();
        }
        async function serverSpin(mode) {
            if(isSpinning||serverSpinBusy)return;
            if(!ensureOnlineAccess()) {
                if (isAutoSpinning) stopAutoSpin();
                return;
            }
            const cfg = PLATE_COUNTRIES[currentCountry] || PLATE_COUNTRIES.RUS;
            const spinCost = mode === 'both'
                ? (cfg.spinCostBoth || cfg.spinBoth || 900)
                : (mode === 'numbers' ? (cfg.spinCostPart || cfg.spinNumbers || 500) : (cfg.spinCostPart || cfg.spinLetters || 500));
            const curOnlineBal = (onlineProfile && Number.isFinite(Number(onlineProfile.balance)))
                ? Number(onlineProfile.balance)
                : balance;
            if (curOnlineBal < spinCost) {
                if (isAutoSpinning) stopAutoSpin();
                notifyUser(`Недостаточно средств для спина (${spinCost} ₽)!`, 'error');
                return;
            }
            serverSpinBusy=true;
            try {
                if (mode === 'both') {
                    pityCounterBoth++;
                    updatePityUI();
                } else if (mode === 'numbers') {
                    pityCounterNum++;
                } else if (mode === 'letters') {
                    pityCounterLet++;
                }
                const data=await onlineRequest('roll',{mode,region:currentReg,pity:pityCounterBoth,country:currentCountry});
                if (data.draft && typeof data.draft.pityCounter === 'number') {
                    pityCounterBoth = data.draft.pityCounter;
                }
                setOnlineProfile(data.profile);
                updateBalance();
                updatePityUI();
                syncServerDraft(data.draft, mode);
                const targets=mode==='both'
                    ? ['cell-l1','cell-n1','cell-n2','cell-n3','cell-l2','cell-l3']
                    : mode==='numbers'?['cell-n1','cell-n2','cell-n3']:['cell-l1','cell-l2','cell-l3'];
                const chars={'cell-l1':currentL1,'cell-n1':currentNum[0], 'cell-n2':currentNum[1],
                    'cell-n3':currentNum[2], 'cell-l2':currentL2,'cell-l3':currentL3};
                executeCellSpin(targets,chars);
            } catch(e) {
                if (isAutoSpinning) stopAutoSpin();
                notifyUser('Спин не выполнен: '+e.message,'error');
            }
            finally {
                serverSpinBusy=false;
                updateBalance();
            }
        }

        function getLuckBonus(pity) {
            const p = Number.isFinite(pity) && pity > 0 ? Math.min(200, pity) : 0;
            return Math.min(200, Math.floor(p * 3));
        }

        function updatePityUI() {
            const countEl = document.getElementById('pity-count');
            const milestoneEl = document.getElementById('pity-next-milestone');
            const fillEl = document.getElementById('pity-progress-fill');
            const boostEl = document.getElementById('pity-boost-badge');
            if (!countEl || !milestoneEl || !fillEl) return;

            countEl.innerText = pityCounterBoth;
            const luckBonus = getLuckBonus(pityCounterBoth);
            if (boostEl) {
                boostEl.innerText = `+${luckBonus}%`;
                boostEl.title = `Шансы на редкие номера увеличены на ${luckBonus}%`;
                if (luckBonus > 0) {
                    boostEl.classList.add('active');
                } else {
                    boostEl.classList.remove('active');
                }
            }

            let nextText = '';
            let percent = 0;

            if (pityCounterBoth < 25) {
                nextText = `До Редкого: ${25 - pityCounterBoth}`;
                percent = Math.min(100, Math.round((pityCounterBoth / 25) * 100));
            } else if (pityCounterBoth < 65) {
                nextText = `До Эпического: ${65 - pityCounterBoth}`;
                percent = Math.min(100, Math.round(((pityCounterBoth - 25) / 40) * 100));
            } else if (pityCounterBoth < 120) {
                nextText = `До Легендарного: ${120 - pityCounterBoth}`;
                percent = Math.min(100, Math.round(((pityCounterBoth - 65) / 55) * 100));
            } else {
                nextText = '🔥 Гарант активен!';
                percent = 100;
            }

            milestoneEl.innerText = nextText;
            fillEl.style.width = `${percent}%`;
        }

        const LADDER_NUMBERS_LOCAL = ['123','234','345','456','567','678','789','987','876','765','654','543','432','321'];

        function pickOrdinary3DigitNumberLocal() {
            for (let attempt = 0; attempt < 40; attempt++) {
                const n = String(101 + Math.floor(Math.random() * 898));
                if (n[0] === n[1] && n[1] === n[2]) continue;
                if (n.endsWith('00')) continue;
                if (LADDER_NUMBERS_LOCAL.includes(n)) continue;
                if (UAE_SPECIAL_3DIGIT_NUMBERS.includes(n)) continue;
                return n;
            }
            return '142';
        }

        function pickOrdinaryUaeNumberLocal() {
            // В реальном Дубае базовые номера RTA — 5-значные (50%), 4-значные (35%) и обычные 3-значные (15%)
            const lenRoll = Math.random();
            if (lenRoll < 0.50) {
                for (let attempt = 0; attempt < 50; attempt++) {
                    const n = String(10000 + Math.floor(Math.random() * 90000));
                    if (n.endsWith('00')) continue;
                    const info = evaluateUaePlateDetails('A', 'A', 'A', n, 'DXB');
                    if (info && info.price < 18000) return n;
                }
                return '48291';
            }
            if (lenRoll < 0.85) {
                for (let attempt = 0; attempt < 50; attempt++) {
                    const n = String(1000 + Math.floor(Math.random() * 9000));
                    if (n.endsWith('00')) continue;
                    const info = evaluateUaePlateDetails('A', 'A', 'A', n, 'DXB');
                    if (info && info.price < 18000) return n;
                }
                return '4829';
            }
            return pickOrdinary3DigitNumberLocal();
        }

        function generateLuckyNumberLocal(forceTier, pity = 0, country = currentCountry) {
            const cCode = String(country || currentCountry || 'RUS').toUpperCase();
            const isIntl = (cCode === 'USA' || cCode === 'UAE' || cCode === 'JPN');

            if (forceTier === 'ultra_special') {
                return randomItem(cCode === 'JPN' ? ['777', '001', '007'] : ['001', '007', '777', '888', '999', '100']);
            }
            if (forceTier === 'legendary') {
                if (cCode === 'UAE') {
                    return randomItem(['1', '5', '7', '9', '2', '8', '11', '77', '88', '99', '777', '7777', '77777']);
                }
                return randomItem(['777', '777', '001', '007', '011', '111', '555', '888', '999']);
            }
            if (forceTier === 'epic') {
                if (cCode === 'UAE') {
                    return randomItem([
                        '111','222','333','444','555','666','777','888','999',
                        '11','22','55','77','88','99','10','20','50','70','63','71',
                        '1971','2020','7007','1000','7000','7777','10000','77777',
                        '2','3','4','6','8'
                    ]);
                }
                return randomItem([
                    '111','222','333','444','555','666','888','999',
                    '100','200','300','400','500','600','700','800','900',
                    '002','003','004','005','006','007','008','009'
                ]);
            }
            if (forceTier === 'rare') {
                if (cCode === 'UAE') {
                    return randomItem([
                        ...LADDER_NUMBERS_LOCAL,
                        '100','200','500','700','900','911','707','101','909','812','720',
                        '12','23','34','45','67','89',
                        '1212','7070','1122','7788','1234','7770',
                        '12345','77000','55000','70707'
                    ]);
                }
                return randomItem(LADDER_NUMBERS_LOCAL);
            }

            const luckBonus = getLuckBonus(pity);
            const roll = Math.floor(Math.random() * 1000);
            const jackpotCutoff = Math.min(15, (isIntl ? 1 : 3) + Math.floor(luckBonus * 0.05));
            if (roll < jackpotCutoff) {
                return randomItem(cCode === 'UAE' ? ['1','5','7','9','2','8','77','777'] : ['777','001','007']);
            }
            const epicCutoff = Math.min(35, (isIntl ? 5 : 12) + Math.floor(luckBonus * 0.15));
            if (roll < epicCutoff) {
                const epicPool = cCode === 'UAE'
                    ? [
                        '111','222','333','444','555','666','777','888','999',
                        '11','22','55','77','88','99','10','20','50','70','63','71',
                        '1971','2020','7007','1000','7000','7777','10000','77777',
                        '2','3','5','7','8','9'
                    ]
                    : [
                        '111','222','333','444','555','666','888','999',
                        '100','200','300','400','500','600','700','800','900',
                        '002','003','004','005','006','007','008','009'
                    ];
                return randomItem(epicPool);
            }
            const ladderCutoff = Math.min(70, (isIntl ? 16 : 30) + Math.floor(luckBonus * 0.3));
            if (roll < ladderCutoff) {
                const rarePool = cCode === 'UAE'
                    ? [
                        ...LADDER_NUMBERS_LOCAL,
                        '100','200','300','500','700','900','911','707','101','909',
                        '12','23','45','67','89',
                        '1212','7070','1122','7788','1234',
                        '12345','77000','70707'
                    ]
                    : LADDER_NUMBERS_LOCAL;
                return randomItem(rarePool);
            }
            return cCode === 'UAE' ? pickOrdinaryUaeNumberLocal() : pickOrdinary3DigitNumberLocal();
        }

        function generateLuckyLettersLocal(forceTier, pity = 0, country = currentCountry) {
            const cCode = String(country || currentCountry || 'RUS').toUpperCase();
            const cfg = PLATE_COUNTRIES[cCode] || PLATE_COUNTRIES.RUS;
            const pool = cfg.letters || lettersArr;
            const elites = cCode === 'UAE'
                ? ['AAA','DDD','BBB','CCC','OOO','III','PPP','XXX','ZZZ']
                : (cfg.eliteLetters || eliteLetters);
            const isIntl = (cCode === 'USA' || cCode === 'UAE' || cCode === 'JPN');

            if (forceTier === 'ultra_special') {
                const specialPool = cCode === 'JPN' ? ['JDM', 'GTR'] : ULTRA_SPECIAL_RUS_SERIES;
                const s = randomItem(specialPool);
                return [s[0], s[1], s[2]];
            }
            if (forceTier === 'legendary') {
                const topElites = cCode === 'RUS'
                    ? ['ААА', 'АМР', 'ВОР', 'ЕКХ', 'ООО', 'ССС', 'МММ', 'СКР']
                    : elites;
                const elite = randomItem(topElites);
                return [elite[0], elite[1], elite[2]];
            }
            if (forceTier === 'epic') {
                if (Math.random() < 0.6) {
                    const elite = randomItem(elites);
                    return [elite[0], elite[1], elite[2]];
                }
                const l = randomItem(pool);
                return [l, l, l];
            }
            if (forceTier === 'rare') {
                const l1 = randomItem(pool);
                let l2 = randomItem(pool);
                if (l2 === l1) l2 = pool[(pool.indexOf(l1) + 1) % pool.length];
                return [l1, l2, l1];
            }

            const luckBonus = getLuckBonus(pity);
            const roll = Math.floor(Math.random() * 1000);
            const eliteCutoff = Math.min(15, (isIntl ? 2 : 4) + Math.floor(luckBonus * 0.05));
            if (roll < eliteCutoff) {
                const elite = randomItem(elites);
                return [elite[0], elite[1], elite[2]];
            }
            const tripleCutoff = Math.min(35, (isIntl ? 6 : 12) + Math.floor(luckBonus * 0.15));
            if (roll < tripleCutoff) {
                const l = randomItem(pool);
                return [l, l, l];
            }
            const mirrorCutoff = Math.min(70, (isIntl ? 20 : 30) + Math.floor(luckBonus * 0.3));
            if (roll < mirrorCutoff) {
                const l1 = randomItem(pool);
                let l2 = randomItem(pool);
                if (l2 === l1) l2 = pool[(pool.indexOf(l1) + 1) % pool.length];
                return [l1, l2, l1];
            }
            for (let attempt = 0; attempt < 30; attempt++) {
                const a = randomItem(pool), b = randomItem(pool), c = randomItem(pool);
                if (a === b && b === c) continue;
                if (elites.includes(a + b + c)) continue;
                if (cCode === 'RUS' && ULTRA_SPECIAL_RUS_SERIES.includes(a + b + c)) continue;
                return [a, b, c];
            }
            return [pool[0], pool[1] || pool[0], pool[2] || pool[0]];
        }

        // --- ВАРИАНТЫ ПРОКРУТОК ---
        function spinNumbers() {
            if(onlineProfile)return serverSpin('numbers');
            if (isSpinning) return;
            const cfg = PLATE_COUNTRIES[currentCountry] || PLATE_COUNTRIES.RUS;
            const cost = cfg.spinNumbers || 500;
            if (balance < cost) return notifyUser(`Недостаточно средств для спина цифр (${cost} ₽)!`);
            deductPlayerBalance(cost, 'Спин цифр');

            pityCounterNum++;
            let n;
            if (pityCounterNum >= currentPityTargetNum) {
                pityCounterNum = 0;
                n = String(currentCountry || 'RUS').toUpperCase() === 'UAE'
                    ? randomItem(['7', '5', '9', '11', '77', '88', '99', '777', '7777', '77777'])
                    : (Math.random() < 0.25 ? '777' : (1 + Math.floor(Math.random() * 9)).toString().repeat(3));
            } else {
                n = generateLuckyNumberLocal(null, pityCounterNum, currentCountry);
            }

            currentNum = n;
            boardHasNumbers = true;
            hasSpunNumSinceSave = true;

            const targets = ['cell-n1', 'cell-n2', 'cell-n3'];
            const finals = { 'cell-n1': n[0], 'cell-n2': n[1], 'cell-n3': n[2] };

            executeCellSpin(targets, finals);
        }

        function spinLetters() {
            if(onlineProfile)return serverSpin('letters');
            if (isSpinning) return;
            const cfg = PLATE_COUNTRIES[currentCountry] || PLATE_COUNTRIES.RUS;
            const cost = cfg.spinLetters || 500;
            if (balance < cost) return notifyUser(`Недостаточно средств для спина букв (${cost} ₽)!`);
            deductPlayerBalance(cost, 'Спин букв');

            pityCounterLet++;
            let l1, l2, l3;
            if (pityCounterLet >= currentPityTargetLet) {
                pityCounterLet = 0;
                let elite = randomItem(cfg.eliteLetters || eliteLetters);
                l1 = elite[0]; l2 = elite[1]; l3 = elite[2];
            } else {
                let letArr = generateLuckyLettersLocal(null, pityCounterLet, currentCountry);
                l1 = letArr[0]; l2 = letArr[1]; l3 = letArr[2];
            }

            currentL1 = l1; currentL2 = l2; currentL3 = l3;
            boardHasLetters = true;
            hasSpunLetSinceSave = true;

            const targets = ['cell-l1', 'cell-l2', 'cell-l3'];
            const finals = { 'cell-l1': l1, 'cell-l2': l2, 'cell-l3': l3 };

            executeCellSpin(targets, finals);
        }

        function spinBoth() {
            if(onlineProfile)return serverSpin('both');
            if (isSpinning) return;
            const cfg = PLATE_COUNTRIES[currentCountry] || PLATE_COUNTRIES.RUS;
            const cost = cfg.spinBoth || 900;
            if (balance < cost) return notifyUser(`Недостаточно средств для полного спина (${cost} ₽)!`);
            deductPlayerBalance(cost, 'Полный спин');

            pityCounterBoth++;
            let forceTier = null;
            if (pityCounterBoth >= 120) forceTier = 'legendary';
            else if (pityCounterBoth >= 65) forceTier = 'epic';
            else if (pityCounterBoth >= 25) forceTier = 'rare';
            else if ((currentCountry === 'RUS' || currentCountry === 'JPN') && Math.floor(Math.random() * 1000) < 2) {
                // 0.2% шанс выбить Ультра-редкий спецномер (СССР ГОСТ, Дипломатический CD, МВД, Военный МО, ФСО или JDM 字光式)
                forceTier = 'ultra_special';
            }

            let n = generateLuckyNumberLocal(forceTier, pityCounterBoth, currentCountry);
            let letArr = generateLuckyLettersLocal(forceTier, pityCounterBoth, currentCountry);
            let l1 = letArr[0], l2 = letArr[1], l3 = letArr[2];

            currentNum = n;
            currentL1 = l1; currentL2 = l2; currentL3 = l3;
            boardHasLetters = true;
            boardHasNumbers = true;
            hasSpunLetSinceSave = true;
            hasSpunNumSinceSave = true;

            updatePityUI();

            const targets = ['cell-l1', 'cell-n1', 'cell-n2', 'cell-n3', 'cell-l2', 'cell-l3'];
            const finals = {
                'cell-l1': l1, 'cell-n1': n[0], 'cell-n2': n[1], 'cell-n3': n[2],
                'cell-l2': l2, 'cell-l3': l3
            };

            executeCellSpin(targets, finals);
        }

        let autoSpinRemaining = Infinity;
        let autoSpinTimerId = null;

        function stopAutoSpin(msg = null) {
            if (autoSpinTimerId) {
                clearTimeout(autoSpinTimerId);
                autoSpinTimerId = null;
            }
            isAutoSpinning = false;
            autoSpinRemaining = 0;
            const btn = document.getElementById('btn-auto-spin');
            if (btn) {
                btn.innerText = "🔄 Авто: ВЫКЛ";
                btn.classList.remove('active');
            }
            if (msg) notifyUser(msg, 'info');
        }

        function startAutoSpin() {
            if (autoSpinTimerId) {
                clearTimeout(autoSpinTimerId);
                autoSpinTimerId = null;
            }
            isAutoSpinning = true;
            const select = document.getElementById('auto-spin-count');
            const countVal = select ? select.value : 'Infinity';
            autoSpinRemaining = countVal === 'Infinity' ? Infinity : (parseInt(countVal, 10) || 10);
            const btn = document.getElementById('btn-auto-spin');
            if (btn) {
                btn.innerText = Number.isFinite(autoSpinRemaining) ? `🔄 Авто: ${autoSpinRemaining}` : "🔄 Авто: ВКЛ";
                btn.classList.add('active');
            }
            runAutoSpinStep();
        }

        function toggleAutoSpin() {
            if (isAutoSpinning) {
                stopAutoSpin();
            } else {
                startAutoSpin();
            }
        }

        function runAutoSpinStep() {
            if (!isAutoSpinning) return;
            if (autoSpinTimerId) {
                clearTimeout(autoSpinTimerId);
                autoSpinTimerId = null;
            }
            if (Number.isFinite(autoSpinRemaining) && autoSpinRemaining <= 0) {
                stopAutoSpin('Авто-прокрутка завершена!');
                return;
            }
            const curBal = (onlineProfile && typeof onlineProfile.balance === 'number')
                ? Number(onlineProfile.balance)
                : balance;
            const cfg = PLATE_COUNTRIES[currentCountry] || PLATE_COUNTRIES.RUS;
            const reqBal = cfg.spinBoth || 900;
            if (curBal < reqBal) {
                stopAutoSpin('Авто-спин остановлен: на активном кошельке недостаточно денег!');
                return;
            }
            if (isSpinning || serverSpinBusy) {
                autoSpinTimerId = setTimeout(runAutoSpinStep, 150);
                return;
            }

            if (Number.isFinite(autoSpinRemaining)) {
                autoSpinRemaining--;
                const btn = document.getElementById('btn-auto-spin');
                if (btn) btn.innerText = `🔄 Авто: ${autoSpinRemaining}`;
            }

            spinBoth();
        }

        async function savePlate() {
            if (!boardHasLetters || !boardHasNumbers || isSpinning) return;
            if (!onlineProfile && mustSpinBothForNextSave && (!hasSpunLetSinceSave || !hasSpunNumSinceSave)) return;
            if(onlineProfile) {
                if(serverSpinBusy)return;
                serverSpinBusy=true;
                try {
                    const data=await onlineRequest('claim');
                    setOnlineProfile(data.profile,true);
                    const rarity=data.plate?.rarity?.text||'Обычный';
                    addExp(rarity);
                    hasSpunLetSinceSave=false;hasSpunNumSinceSave=false;
                    mustSpinBothForNextSave=true;
                    checkCanSaveButton();
                    notifyUser(`✅ ${data.plate.text} добавлен на сервер. Теперь его можно продать на рынке!`,'success');
                }catch(e){notifyUser('Не удалось сохранить номер: '+e.message,'error');}
                finally{serverSpinBusy=false;}
                return;
            }
            let pText = formatPlateText(currentL1, currentL2, currentL3, currentNum, currentReg, currentCountry);
            let price = calculatePrice();
            let r = getRarity(price);

            const savedEntry = { text: pText, price: price, rarity: r, country: currentCountry, createdAt: Date.now() };
            inventory.unshift(savedEntry);
            recordRecentRareDrop(savedEntry);
            addExp(r.text);

            hasSpunLetSinceSave = false;
            hasSpunNumSinceSave = false;
            mustSpinBothForNextSave = true;

            playCashSound();
            renderInventory();
            checkCanSaveButton();
            logPlayerActivity('Сохранил номер', `Сохранил в инвентарь госномер «${pText}» (${escapeHtml(r.text)}, ${price.toLocaleString('ru-RU')} ₽)`);
            saveProgress();
            notifyUser(`Номер "${pText}" сохранен в инвентарь!`);
        }

        async function sellCurrentPlate(isAuto = false) {
            if (!boardHasLetters || !boardHasNumbers) return;
            if (isSpinning && !isAuto) return;
            if (!isAuto) {
                if (!onlineProfile && mustSpinBothForNextSave && (!hasSpunLetSinceSave || !hasSpunNumSinceSave)) return;
                const btnSave = document.getElementById('btn-save');
                if (btnSave && btnSave.disabled) return;
            }

            if (onlineProfile) {
                if (serverSpinBusy && !isAuto) return;
                serverSpinBusy = true;
                try {
                    const data = await onlineRequest('claim', { region: currentReg, country: currentCountry });
                    setOnlineProfile(data.profile, true);
                    const rarity = data.plate?.rarity?.text || 'Обычный';
                    addExp(rarity);
                    hasSpunLetSinceSave = false;
                    hasSpunNumSinceSave = false;
                    mustSpinBothForNextSave = true;
                    const idx = inventory.findIndex(p => p && (p.id === data.plate?.id || p.text === data.plate?.text));
                    if (idx >= 0) {
                        sellPlate(idx, isAuto);
                    } else if (inventory.length > 0) {
                        sellPlate(0, isAuto);
                    } else if (data.plate) {
                        creditPlayerBalance(data.plate.price, `Продажа госномера «${data.plate.text}»`);
                        playCashSound();
                        saveProgress();
                        if (!isAuto) {
                            notifyUser(`Номер «${data.plate.text}» продан за ${Number(data.plate.price).toLocaleString('ru-RU')} ₽!`, 'success');
                        }
                    }
                    checkCanSaveButton();
                } catch(e) {
                    notifyUser('Не удалось продать номер: ' + e.message, 'error');
                } finally {
                    serverSpinBusy = false;
                }
                return;
            }

            let pText = formatPlateText(currentL1, currentL2, currentL3, currentNum, currentReg, currentCountry);
            let price = calculatePrice();
            let r = getRarity(price);

            creditPlayerBalance(price, `Продажа госномера «${pText}»`);
            addExp(r.text);

            hasSpunLetSinceSave = false;
            hasSpunNumSinceSave = false;
            mustSpinBothForNextSave = true;

            playCashSound();
            renderInventory();
            checkCanSaveButton();
            logPlayerActivity('Продал номер', `Продал госномер «${pText}» (${escapeHtml(r.text)}, +${price.toLocaleString('ru-RU')} ₽)`);
            saveProgress();
            if (!isAuto) {
                notifyUser(`Номер «${pText}» продан за ${price.toLocaleString('ru-RU')} ₽!`);
            }
        }

        // --- КЕЙСЫ (CS:GO HORIZONTAL ROULETTE) ---
        function getRarityObjForTier(targetRarity, fallbackPrice = 0) {
            if (targetRarity === 'Ультра-спец' || targetRarity === 'УЛЬТРА-СПЕЦ') {
                return { text: "БЛАТНОЙ", color: "white", bg: "linear-gradient(45deg, #b91c1c, #d97706)", border: "1px solid #ffd700", glow: "blatnoy" };
            }
            if (targetRarity === 'Мифический' || targetRarity === 'МИФИЧЕСКИЙ') {
                return { text: "Мифический", color: "white", bg: "linear-gradient(45deg, #e0115f, #ffd700)", border: "1px solid #ffd700", glow: "blatnoy" };
            }
            if (targetRarity === 'БЛАТНОЙ') {
                return { text: "БЛАТНОЙ", color: "white", bg: "linear-gradient(45deg, #e0115f, #ffd700)", border: "1px solid #ffd700", glow: "blatnoy" };
            }
            if (targetRarity === 'Крутой') {
                return { text: "Крутой", color: "white", bg: "linear-gradient(45deg, #ff1493, #8a2be2)", border: "1px solid #ff1493", glow: "blatnoy" };
            }
            if (targetRarity === 'Легендарный') {
                return { text: "Легендарный", color: "black", bg: "#f59e0b", border: "1px solid black", glow: "legendary" };
            }
            if (targetRarity === 'Эпический') {
                return { text: "Эпический", color: "white", bg: "#8b5cf6", border: "1px solid black", glow: "epic" };
            }
            if (targetRarity === 'Супер редкий') {
                return { text: "Супер редкий", color: "white", bg: "#ef4444", border: "1px solid black", glow: "super" };
            }
            if (targetRarity === 'Редкий') {
                return { text: "Редкий", color: "white", bg: "#10b981", border: "1px solid black", glow: "rare" };
            }
            if (targetRarity === 'Необычный') {
                return { text: "Необычный", color: "white", bg: "#3b82f6", border: "1px solid black", glow: "uncommon" };
            }
            if (targetRarity === 'Обычный') {
                return { text: "Обычный", color: "white", bg: "transparent", border: "none", glow: "none" };
            }
            return getRarity(fallbackPrice);
        }

        function forcePlate(targetRarity, countryOverride) {
            const rawOverride = countryOverride ? String(countryOverride).toUpperCase() : '';
            const cCode = (rawOverride && COUNTRY_CONFIGS[rawOverride])
                ? rawOverride
                : (currentCaseCountry || currentCountry || 'RUS');
            const cfg = COUNTRY_CONFIGS[cCode] || COUNTRY_CONFIGS.RUS;
            const pool = cfg.letters || lettersArr;
            const elites = cfg.eliteLetters || eliteLetters;

            const ordinaryRegionsMap = {
                RUS: ['50', '23', '16', '78', '777', '77', '99'],
                KZ: ['05', '07', '09', '13', '01', '02'],
                USA: ['TX', 'IL', 'WA', 'GA', 'CA', 'NY', 'FL'],
                UAE: ['SHJ', 'AJM', 'RAK', 'DXB', 'AUH'],
                JPN: ['FKO', 'KBE', 'KYO', 'CHB', 'TKY', 'YKH', 'OSK']
            };
            const capitalRegionsMap = {
                RUS: ['77', '777', '97'],
                KZ: ['01', '02'],
                USA: ['CA', 'NY', 'FL'],
                UAE: ['DXB', 'AUH'],
                JPN: ['TKY', 'YKH', 'OSK']
            };
            const legendarySeriesMap = {
                RUS: ['ААА', 'МММ', 'ООО', 'ХХХ', 'АМР', 'ЕКХ', 'ВОР'],
                KZ: ['VIP', 'AAA', 'MMM', 'ZZZ', 'XXX'],
                USA: ['VIP', 'AAA', 'NYC', 'USA', 'LAX'],
                UAE: ['AAA', 'DDD', 'BBB', 'OOO', 'III', 'PPP'],
                JPN: ['JDM', 'TKY', 'GTR', 'NSM', 'TRD', 'STI']
            };
            const mythicTemplatesMap = {
                RUS: [
                    { l: 'ААА', num: '777', reg: '777' },
                    { l: 'ЕКХ', num: '777', reg: '77' },
                    { l: 'АМР', num: '001', reg: '97' },
                    { l: 'ВОР', num: '777', reg: '777' },
                    { l: 'МОС', num: '001', reg: '77' },
                    { l: 'КМН', num: '001', reg: '77' },
                    { l: 'УМВ', num: '001', reg: '77' },
                    { l: 'ВМО', num: '001', reg: '77' },
                    { l: 'КРМ', num: '001', reg: '77' }
                ],
                KZ: [
                    { l: 'ZZZ', num: '777', reg: '01' },
                    { l: 'VIP', num: '001', reg: '01' },
                    { l: 'AAA', num: '777', reg: '02' }
                ],
                USA: [
                    { l: 'VIP', num: '777', reg: 'CA' },
                    { l: 'USA', num: '001', reg: 'NY' },
                    { l: 'MIA', num: '777', reg: 'FL' }
                ],
                UAE: [
                    { l: 'PPP', num: '007', reg: 'DXB' },
                    { l: 'DDD', num: '005', reg: 'DXB' },
                    { l: 'AAA', num: '009', reg: 'DXB' },
                    { l: 'DDD', num: '001', reg: 'DXB' },
                    { l: 'OOO', num: '009', reg: 'DXB' }
                ],
                JPN: [
                    { l: 'JDM', num: '777', reg: 'TKY' },
                    { l: 'GTR', num: '001', reg: 'YKH' },
                    { l: 'TKY', num: '777', reg: 'TKY' }
                ]
            };

            const pickOrdinaryLetters = () => {
                let a = randomItem(pool), b = randomItem(pool), c = randomItem(pool);
                let guard = 0;
                while ((a === b || b === c || a === c || elites.includes(a + b + c) || (cCode === 'RUS' && ULTRA_SPECIAL_RUS_SERIES.includes(a + b + c))) && guard < 40) {
                    a = randomItem(pool); b = randomItem(pool); c = randomItem(pool);
                    guard++;
                }
                return [a, b, c];
            };

            let l1 = pool[0], l2 = pool[1] || pool[0], l3 = pool[2] || pool[0];
            let num = '142';
            let reg = (cCode === currentCountry && currentReg) ? currentReg : (cfg.defaultReg || '777');
            let price = 0;
            let matched = false;

            const applyDeterministicPattern = (tier) => {
                if (tier === 'Ультра-спец' || tier === 'УЛЬТРА-СПЕЦ') {
                    const s = cCode === 'JPN' ? randomItem(['JDM', 'GTR']) : randomItem(ULTRA_SPECIAL_RUS_SERIES);
                    l1 = s[0]; l2 = s[1]; l3 = s[2];
                    num = randomItem(['001', '777', '007']);
                    reg = cCode === 'JPN' ? 'TKY' : '77';
                } else if (tier === 'Мифический' || tier === 'МИФИЧЕСКИЙ' || tier === 'БЛАТНОЙ') {
                    const tpl = randomItem(mythicTemplatesMap[cCode] || mythicTemplatesMap.RUS);
                    l1 = tpl.l[0]; l2 = tpl.l[1]; l3 = tpl.l[2];
                    num = (tier === 'БЛАТНОЙ' && cCode === 'RUS' && tpl.l === 'ЕКХ') ? '011' : tpl.num;
                    reg = tpl.reg;
                } else if (tier === 'Крутой' || tier === 'Легендарный') {
                    const series = randomItem(legendarySeriesMap[cCode] || legendarySeriesMap.RUS);
                    l1 = series[0]; l2 = series[1]; l3 = series[2];
                    num = cCode === 'UAE'
                        ? randomItem(['11', '77', '88', '99', '777', '7777', '77777'])
                        : randomItem(['777', '001', '888', '999']);
                    reg = randomItem(capitalRegionsMap[cCode] || capitalRegionsMap.RUS);
                } else if (tier === 'Эпический') {
                    [l1, l2, l3] = pickOrdinaryLetters();
                    num = cCode === 'UAE'
                        ? randomItem(['777', '111', '555', '888', '999', '50', '70', '63', '71', '1971', '1000', '7007', '10000'])
                        : randomItem(['001', '777', '666', '111', '222', '333', '444', '555', '888', '999']);
                    reg = randomItem(capitalRegionsMap[cCode] || capitalRegionsMap.RUS);
                } else if (tier === 'Супер редкий') {
                    [l1, l2, l3] = pickOrdinaryLetters();
                    num = cCode === 'UAE'
                        ? randomItem(['12', '23', '34', '45', '56', '67', '78', '89', '1212', '7070', '7788', '1234', '12345'])
                        : randomItem(['007', '002', '003', '004', '005', '006', '008', '009']);
                    reg = randomItem(ordinaryRegionsMap[cCode] || ordinaryRegionsMap.RUS);
                } else if (tier === 'Редкий') {
                    [l1, l2, l3] = pickOrdinaryLetters();
                    num = cCode === 'UAE'
                        ? randomItem(['100', '200', '300', '500', '700', '900', '911', '707', '101', '909', '123', '234', '77000', '55000'])
                        : randomItem(['100', '200', '300', '500', '700', '900', '123', '234', '345', '456']);
                    reg = randomItem(ordinaryRegionsMap[cCode] || ordinaryRegionsMap.RUS);
                } else if (tier === 'Необычный') {
                    [l1, l2, l3] = pickOrdinaryLetters();
                    num = cCode === 'UAE'
                        ? randomItem(['252', '818', '4829', '7315', '3942', '48291', '73920', '51842'])
                        : randomItem(['101', '252', '707', '818', '909', '010', '020', '030', '040', '050', '070', '090']);
                    reg = randomItem(ordinaryRegionsMap[cCode] || ordinaryRegionsMap.RUS);
                } else {
                    [l1, l2, l3] = pickOrdinaryLetters();
                    num = cCode === 'UAE'
                        ? randomItem(['48291', '73920', '51842', '4829', '7315', '142'])
                        : randomItem(['142', '385', '619', '258', '369', '417', '582', '638']);
                    reg = randomItem(ordinaryRegionsMap[cCode] || ordinaryRegionsMap.RUS);
                }
            };

            for (let i = 0; i < 60; i++) {
                applyDeterministicPattern(targetRarity);
                price = calculatePlatePriceForCountry(cCode, l1, l2, l3, num, reg);
                const baseEquivalentPrice = Math.round(price / (cfg.priceMult || 1));
                const r = getRarity(baseEquivalentPrice);
                const bonusMult = cCode === 'UAE' ? 2.2 : (cCode === 'JPN' ? 1.85 : (cCode === 'USA' ? 1.6 : (cCode === 'KZ' ? 1.3 : 1)));
                const bonusEquivalentPrice = cCode === 'RUS'
                    ? price
                    : Math.max(450, Math.round((price - (cfg.basePrice || 450)) / bonusMult + 450));
                const rBonus = getRarity(bonusEquivalentPrice);
                const rActual = getRarity(price);

                if (
                    r.text === targetRarity ||
                    rBonus.text === targetRarity ||
                    rActual.text === targetRarity ||
                    ((targetRarity === 'Мифический' || targetRarity === 'МИФИЧЕСКИЙ' || targetRarity === 'Ультра-спец') && price >= 5000000)
                ) {
                    matched = true;
                    break;
                }
            }

            if (!matched) {
                applyDeterministicPattern(targetRarity);
                price = calculatePlatePriceForCountry(cCode, l1, l2, l3, num, reg);
            }

            return {
                text: formatPlateText(l1, l2, l3, num, reg, cCode),
                price: price,
                rarity: getRarityObjForTier(targetRarity, price),
                country: cCode
            };
        }
        if (typeof window !== 'undefined') {
            window.forcePlate = forcePlate;
        }

        function getCarRarity(price) {
            if (price >= 50000000) return { text: "МИФИЧЕСКИЙ", bg: "linear-gradient(135deg, #ef4444, #ec4899)", color: "#fff", border: "2px solid #ef4444", glow: "0 0 16px rgba(239, 68, 68, 0.8)" };
            if (price >= 15000000) return { text: "Легендарный", bg: "#f59e0b", color: "#000", border: "2px solid #f59e0b", glow: "0 0 12px rgba(245, 158, 11, 0.6)" };
            if (price >= 5000000) return { text: "Эпический", bg: "#ec4899", color: "#fff", border: "2px solid #ec4899", glow: "0 0 10px rgba(236, 72, 153, 0.5)" };
            if (price >= 2000000) return { text: "Супер редкий", bg: "#8b5cf6", color: "#fff", border: "2px solid #8b5cf6", glow: "none" };
            if (price >= 700000) return { text: "Редкий", bg: "#3b82f6", color: "#fff", border: "2px solid #3b82f6", glow: "none" };
            return { text: "Обычный", bg: "#475569", color: "#fff", border: "1px solid #475569", glow: "none" };
        }

