        function triggerShowroomHorn() {
            const car = myCars[currentStylingCarIndex];
            const hasSgu = !!(car && car.styling && car.styling.sgu && car.styling.sgu !== 'none');
            if (sound) {
                if (hasSgu && typeof sound.sgu === 'function') {
                    sound.sgu();
                } else if (typeof sound.horn === 'function') {
                    sound.horn({ sgu: hasSgu, truck: false });
                }
            }
            if (car3DShowroom && typeof car3DShowroom.flashHorn === 'function') {
                car3DShowroom.flashHorn();
            } else if (car3DShowroom) {
                const wasOn = !!car3DShowroom.headlightsOn;
                car3DShowroom.toggleHeadlights();
                setTimeout(() => {
                    if (car3DShowroom && !!car3DShowroom.headlightsOn !== wasOn) {
                        car3DShowroom.toggleHeadlights();
                        updateShowroomButtonsState();
                    }
                }, 260);
            }
            const btn = document.getElementById('btn-show-horn');
            if (btn) {
                btn.classList.add('active');
                setTimeout(() => btn.classList.remove('active'), 320);
            }
        }
        window.triggerShowroomHorn = triggerShowroomHorn;

        // =====================================================================
        // 🏎️ GARAGE 3D SHOWROOM (Интерактивный 3D-подиум прямо в Гараже)
        // =====================================================================
        let garage3DShowroom = null;
        let activeGarageCarIndex = 0;
        let garageViewMode = '3d';

        function updateGarageButtonsState() {
            if (!garage3DShowroom) return;
            const btnDoors = document.getElementById('btn-gshow-doors');
            const btnHood = document.getElementById('btn-gshow-hood');
            const btnTrunk = document.getElementById('btn-gshow-trunk');
            const btnLights = document.getElementById('btn-gshow-lights');

            if (btnDoors) {
                btnDoors.style.opacity = '1';
                btnDoors.classList.remove('disabled');
                btnDoors.classList.toggle('active', !!garage3DShowroom.doorsOpen);
            }
            if (btnHood) {
                btnHood.style.opacity = '1';
                btnHood.classList.remove('disabled');
                btnHood.classList.toggle('active', !!garage3DShowroom.hoodOpen);
            }
            if (btnTrunk) {
                btnTrunk.style.opacity = '1';
                btnTrunk.classList.remove('disabled');
                btnTrunk.classList.toggle('active', !!garage3DShowroom.trunkOpen);
            }
            if (btnLights) {
                btnLights.classList.toggle('active', !!garage3DShowroom.headlightsOn);
            }
        }

        function initGarage3DShowroom() {
            const podiumCard = document.getElementById('garage-3d-podium-card');
            if (!Array.isArray(myCars) || myCars.length === 0) {
                if (podiumCard) podiumCard.style.display = 'none';
                if (garage3DShowroom) garage3DShowroom.stop();
                return;
            }
            if (typeof Car3DManager === 'undefined' || typeof window.THREE === 'undefined' || (typeof Car3DManager.isWebGLAvailable === 'function' && !Car3DManager.isWebGLAvailable())) {
                if (podiumCard) podiumCard.style.display = 'none';
                return;
            }
            if (podiumCard) podiumCard.style.display = 'block';

            activeGarageCarIndex = Math.max(0, Math.min(activeGarageCarIndex, myCars.length - 1));

            if (!garage3DShowroom) {
                garage3DShowroom = new Car3DManager.Car3DShowroom('garage-preview-3d-wrap', {
                    fitModelBounds: Boolean(window.NOMERA_AUTHORS_PREVIEW),
                    autoRotate: false,
                    autoRotateSpeed: 0.007,
                    showPodium: true,
                    loaderId: 'garage-3d-loader',
                    loaderTextId: 'garage-3d-loader-text'
                });
                garage3DShowroom.onCapabilitiesChange = () => {
                    updateGarageButtonsState();
                };
            } else {
                garage3DShowroom.onCapabilitiesChange = () => {
                    updateGarageButtonsState();
                };
                garage3DShowroom.resize();
                garage3DShowroom.start();
            }
            window.garageShowroom = garage3DShowroom;

            selectGarageCarForPodium(activeGarageCarIndex, false);
        }
        window.initGarage3DShowroom = initGarage3DShowroom;

        function toggleGaragePodiumCollapse(forceOpen = null) {
            const stage = document.getElementById('garage-preview-stage');
            const switchBar = document.getElementById('garage-view-switch');
            const icon = document.getElementById('garage-podium-toggle-icon');
            const label = document.getElementById('garage-podium-toggle-label');
            if (!stage) return;
            const currentlyCollapsed = stage.style.display === 'none';
            const shouldOpen = (forceOpen !== null) ? forceOpen : currentlyCollapsed;
            if (shouldOpen) {
                stage.style.display = 'block';
                if (switchBar) switchBar.style.display = 'flex';
                if (icon) icon.textContent = '▲';
                if (label) label.textContent = 'Свернуть 3D';
                if (garage3DShowroom) {
                    garage3DShowroom.resize();
                    garage3DShowroom.start();
                }
            } else {
                stage.style.display = 'none';
                if (switchBar) switchBar.style.display = 'none';
                if (icon) icon.textContent = '▼';
                if (label) label.textContent = 'Развернуть 3D';
                if (garage3DShowroom) {
                    garage3DShowroom.stop();
                }
            }
        }
        window.toggleGaragePodiumCollapse = toggleGaragePodiumCollapse;

        function rotateGarageShowroom(delta) {
            if (garage3DShowroom && typeof garage3DShowroom.rotateBy === 'function') {
                garage3DShowroom.rotateBy(delta);
            }
        }
        window.rotateGarageShowroom = rotateGarageShowroom;

        function renderGarageCarSidebarList() {
            if (typeof document === 'undefined') return;
            const listEl = document.getElementById('garage-car-sidebar-list');
            if (!listEl) return;
            if (!Array.isArray(myCars) || myCars.length === 0) {
                listEl.innerHTML = `<div style="font-size:12px; color:var(--text-muted); padding:12px; text-align:center;">В гараже пока нет машин</div>`;
                return;
            }
            listEl.innerHTML = myCars.map((car, idx) => {
                if (!car) return '';
                const isActive = idx === activeGarageCarIndex;
                const plateText = (car.plate && (car.plate.text || car.plate)) ||
                    (car.attachedPlate && (car.attachedPlate.text || car.attachedPlate)) || '';
                const subText = plateText ? `🏷️ ${plateText}` : (car.category || 'Без номера');
                return `
                    <button type="button" class="garage-side-car-item ${isActive ? 'active' : ''}" onclick="selectGarageCarForPodium(${idx})">
                        <img src="${getCarSpriteDataUrl(car.name)}" class="garage-side-car-thumb" alt="${escapeHtml(car.name)}" onerror="this.onerror=null; this.src='./icons/car-placeholder.svg';">
                        <div class="garage-side-car-meta">
                            <div class="garage-side-car-name">${escapeHtml(car.name)}</div>
                            <div class="garage-side-car-sub">${escapeHtml(subText)}</div>
                        </div>
                    </button>`;
            }).join('');
        }
        window.renderGarageCarSidebarList = renderGarageCarSidebarList;

        let activeGarageInspectorTab = 'overview';
        let activeGarageSubView = 'showroom';

        function switchGarageSubView(view = 'showroom') {
            const validView = (view === 'shop' || view === 'fleet') ? view : 'showroom';
            activeGarageSubView = validView;
            if (window.NOMERA_AUTHORS_PREVIEW && validView === 'shop') renderShopCars();
            if (typeof document === 'undefined') return validView;

            const btnShowroom = document.getElementById('btn-garage-sub-showroom');
            const btnShop = document.getElementById('btn-garage-sub-shop');
            const btnFleet = document.getElementById('btn-garage-sub-fleet');
            if (btnShowroom && btnShowroom.classList) btnShowroom.classList.toggle('active', validView === 'showroom');
            if (btnShop && btnShop.classList) btnShop.classList.toggle('active', validView === 'shop');
            if (btnFleet && btnFleet.classList) btnFleet.classList.toggle('active', validView === 'fleet');

            const showroomEl = document.getElementById('garage-showroom-layout') ||
                (typeof document.querySelector === 'function' ? document.querySelector('#garage .garage-luxury-layout') : null);
            const shopHeader = document.getElementById('garage-shop-section');
            const shopFilters = document.getElementById('dealership-filter-bar');
            const shopGrid = document.getElementById('garage-list');
            const fleetCard = document.getElementById('garage-fleet-card');
            const myCarsEl = document.getElementById('my-cars');

            if (showroomEl && showroomEl.classList) showroomEl.classList.toggle('hidden', validView !== 'showroom');
            if (shopHeader && shopHeader.classList) shopHeader.classList.toggle('hidden', validView !== 'shop');
            if (shopFilters && shopFilters.classList) shopFilters.classList.toggle('hidden', validView !== 'shop');
            if (shopGrid && shopGrid.classList) shopGrid.classList.toggle('hidden', validView !== 'shop');
            if (fleetCard && fleetCard.classList) fleetCard.classList.toggle('hidden', validView !== 'fleet');
            if (myCarsEl && myCarsEl.classList) myCarsEl.classList.toggle('hidden', validView !== 'fleet');

            if (validView === 'showroom') {
                if (garage3DShowroom) {
                    try {
                        garage3DShowroom.resize();
                        garage3DShowroom.start();
                        garage3DShowroom.requestRender();
                    } catch (_) {}
                }
            } else if (garage3DShowroom) {
                try { garage3DShowroom.stop(); } catch (_) {}
            }
            if (validView === 'fleet' && typeof renderFleetBusiness === 'function') {
                renderFleetBusiness();
            }
            return validView;
        }
        window.switchGarageSubView = switchGarageSubView;

        function switchGarageInspectorTab(tabId = 'overview') {
            const validTabs = ['overview', 'tuning', 'plates', 'styling', 'camera'];
            const nextTab = validTabs.includes(tabId) ? tabId : 'overview';
            activeGarageInspectorTab = nextTab;
            if (typeof document === 'undefined') return nextTab;

            if (typeof document.querySelectorAll === 'function') {
                document.querySelectorAll('#garage-active-inspector [data-garage-tab]').forEach(btn => {
                    const bTab = typeof btn.getAttribute === 'function' ? btn.getAttribute('data-garage-tab') : (btn.dataset && btn.dataset.garageTab);
                    if (btn.classList) btn.classList.toggle('active', bTab === nextTab);
                });
                document.querySelectorAll('#garage-active-inspector [data-garage-tab-panel]').forEach(panel => {
                    const pTab = typeof panel.getAttribute === 'function' ? panel.getAttribute('data-garage-tab-panel') : (panel.dataset && panel.dataset.garageTabPanel);
                    if (panel.classList) panel.classList.toggle('hidden', pTab !== nextTab);
                });
            }
            const camPanel = document.getElementById('garage-inspector-camera-panel');
            if (camPanel && camPanel.classList) {
                camPanel.classList.toggle('hidden', nextTab !== 'camera');
            }
            return nextTab;
        }
        window.switchGarageInspectorTab = switchGarageInspectorTab;

        function prevGarageCar() {
            if (!Array.isArray(myCars) || myCars.length === 0) return;
            const prevIdx = (activeGarageCarIndex - 1 + myCars.length) % myCars.length;
            selectGarageCarForPodium(prevIdx);
            if (typeof playTick === 'function') playTick();
        }
        window.prevGarageCar = prevGarageCar;

        function nextGarageCar() {
            if (!Array.isArray(myCars) || myCars.length === 0) return;
            const nextIdx = (activeGarageCarIndex + 1) % myCars.length;
            selectGarageCarForPodium(nextIdx);
            if (typeof playTick === 'function') playTick();
        }
        window.nextGarageCar = nextGarageCar;

        function renderGarageActiveCarInspector(index = activeGarageCarIndex) {
            if (typeof document === 'undefined') return;
            const bodyEl = document.getElementById('garage-inspector-body');
            if (!bodyEl) return;
            if (!Array.isArray(myCars) || myCars.length === 0 || !myCars[index]) {
                bodyEl.innerHTML = `<div style="color:var(--text-muted); font-size:12.5px; padding:14px 0;">Автомобиль не выбран.</div>`;
                return;
            }
            const car = myCars[index];
            if (typeof NomeraRaceEconomy !== 'undefined' && typeof NomeraRaceEconomy.ensureCar === 'function') {
                NomeraRaceEconomy.ensureCar(car);
            }
            const template = carsData.find(c => c.name === car.name) || {};
            const basePrice = Number(car.basePrice || template.price || 100000);
            const plateObj = car.plate || null;
            const plateText = (plateObj && (plateObj.text || plateObj)) || '';
            const platePrice = Number(plateObj && plateObj.price) || 0;
            const totalValue = basePrice + platePrice;

            const upg = car.upgrades || { engine: 0, handling: 0, economy: 0, nitro: 0 };
            const baseSpeed = Math.min(410, Math.round(170 + Math.log10(Math.max(50000, basePrice)) * 32 + (upg.engine || 0) * 12));
            const speedPct = Math.min(100, Math.round((baseSpeed / 410) * 100));
            const accelPct = Math.min(100, Math.round(45 + Math.log10(Math.max(50000, basePrice)) * 7 + (upg.engine || 0) * 8 + (upg.nitro || 0) * 4));
            const handlingPct = Math.min(100, Math.round(52 + (upg.handling || 0) * 9));
            const nitroPct = Math.min(100, Math.round(40 + (upg.nitro || 0) * 12));

            const syn = plateText ? getCarPlateSynergy(car.name, plateText) : null;
            const synHtml = syn
                ? `<div style="margin-top:6px; font-size:11px; color:#fbbf24; font-weight:800;">${syn.icon} Синергия «${escapeHtml(syn.title)}»: +${syn.bonusPct}% к наградам</div>`
                : '';

            const plateSlotHtml = plateText
                ? `<div class="inspector-plate-slot">
                        <div style="font-size:10px; font-weight:800; color:var(--text-muted); text-transform:uppercase; margin-bottom:6px;">УСТАНОВЛЕННЫЙ ГОСНОМЕР</div>
                        <div class="mini-plate ${getMiniPlateCountryClass(plateText)}" style="font-size:15px; padding:5px 12px;">${renderMiniPlateInnerHtml(plateText)}</div>
                        ${platePrice > 0 ? `<div style="font-size:11.5px; color:#fbbf24; font-weight:800; margin-top:6px;">Оценка номера: ${platePrice.toLocaleString('ru-RU')} ₽</div>` : ''}
                        ${synHtml}
                        <div style="display:grid; grid-template-columns:1fr 1fr; gap:6px; margin-top:8px;">
                            <button type="button" class="case-open-btn" onclick="openAttachModal(${index})">🔄 Заменить</button>
                            <button type="button" class="case-open-btn" onclick="detachPlate(${index})">🔧 Снять</button>
                        </div>
                   </div>`
                : `<div class="inspector-plate-slot">
                        <div style="font-size:11px; color:var(--text-muted); margin-bottom:8px;">Госномер не установлен</div>
                        <button type="button" class="btn btn-red-cta" style="margin:0; padding:8px 12px; font-size:12px;" onclick="openAttachModal(${index})">🏷️ Выбрать из коллекции</button>
                   </div>`;

            const engLvl = upg.engine || 0;
            const hndLvl = upg.handling || 0;
            const nitLvl = upg.nitro || 0;
            const ecoLvl = upg.economy || 0;
            const maxLvl = (typeof NomeraRaceEconomy !== 'undefined' && NomeraRaceEconomy.MAX_LEVEL) ? NomeraRaceEconomy.MAX_LEVEL : 5;
            const engCost = (typeof NomeraRaceEconomy !== 'undefined') ? NomeraRaceEconomy.upgradeCost(basePrice, 'engine', engLvl) : null;
            const hndCost = (typeof NomeraRaceEconomy !== 'undefined') ? NomeraRaceEconomy.upgradeCost(basePrice, 'handling', hndLvl) : null;
            const nitCost = (typeof NomeraRaceEconomy !== 'undefined') ? NomeraRaceEconomy.upgradeCost(basePrice, 'nitro', nitLvl) : null;
            const ecoCost = (typeof NomeraRaceEconomy !== 'undefined') ? NomeraRaceEconomy.upgradeCost(basePrice, 'economy', ecoLvl) : null;
            const cond = Math.round(Number(car.condition ?? 100));
            const repCost = (typeof NomeraRaceEconomy !== 'undefined' && cond < 100) ? NomeraRaceEconomy.repairCost(basePrice, cond) : 0;

            const curTab = activeGarageInspectorTab || 'overview';

            bodyEl.innerHTML = `
                <div class="inspector-car-header">
                    <h4 class="inspector-car-title">${escapeHtml(car.name)}</h4>
                    <div style="display:flex; justify-content:space-between; align-items:center; font-size:12px;">
                        <span style="color:var(--text-muted);">${escapeHtml(car.category || template.category || 'Авто')} • Состояние: <b style="color:${cond >= 80 ? '#34d399' : '#fbbf24'};">${cond}%</b></span>
                        <span class="inspector-car-price">${totalValue.toLocaleString('ru-RU')} ₽</span>
                    </div>
                </div>

                <!-- ВКЛАДКА 1: ОБЗОР -->
                <div class="garage-inspector-panel ${curTab === 'overview' ? '' : 'hidden'}" data-garage-tab-panel="overview">
                    ${plateSlotHtml}
                    <div class="inspector-telemetry-list">
                        <div class="inspector-stat-row">
                            <div class="inspector-stat-head"><span>⚡ Макс. скорость</span><b>${baseSpeed} км/ч</b></div>
                            <div class="inspector-stat-bar-bg"><div class="inspector-stat-bar-fill" style="width:${speedPct}%;"></div></div>
                        </div>
                        <div class="inspector-stat-row">
                            <div class="inspector-stat-head"><span>🚀 Динамика разгона</span><b>${accelPct}/100</b></div>
                            <div class="inspector-stat-bar-bg"><div class="inspector-stat-bar-fill" style="width:${accelPct}%;"></div></div>
                        </div>
                        <div class="inspector-stat-row">
                            <div class="inspector-stat-head"><span>🛞 Управляемость</span><b>${handlingPct}/100</b></div>
                            <div class="inspector-stat-bar-bg"><div class="inspector-stat-bar-fill" style="width:${handlingPct}%;"></div></div>
                        </div>
                        <div class="inspector-stat-row">
                            <div class="inspector-stat-head"><span>🔥 Запас нитро (Stage ${nitLvl})</span><b>${nitroPct}/100</b></div>
                            <div class="inspector-stat-bar-bg"><div class="inspector-stat-bar-fill" style="width:${nitroPct}%;"></div></div>
                        </div>
                    </div>
                </div>

                <!-- ВКЛАДКА 2: ТЮНИНГ STAGE -->
                <div class="garage-inspector-panel ${curTab === 'tuning' ? '' : 'hidden'}" data-garage-tab-panel="tuning">
                    <div id="inspector-tuning-box" style="display:flex; flex-direction:column; gap:6px;">
                        <div class="luxury-panel-eyebrow" style="margin-bottom:2px;">ТЕХНИЧЕСКИЙ ТЮНИНГ (STAGE ${engLvl + hndLvl + nitLvl + ecoLvl})</div>
                        <button type="button" class="case-open-btn" style="display:flex; justify-content:space-between; padding:8px 10px;" onclick="upgradeGarageCar(${index}, 'engine')" ${engCost === null ? 'disabled' : ''}>
                            <span>🛠️ Двигатель (${engLvl}/${maxLvl})</span>
                            <b style="color:#fbbf24;">${engCost !== null ? engCost.toLocaleString('ru-RU') + ' ₽' : 'MAX'}</b>
                        </button>
                        <button type="button" class="case-open-btn" style="display:flex; justify-content:space-between; padding:8px 10px;" onclick="upgradeGarageCar(${index}, 'handling')" ${hndCost === null ? 'disabled' : ''}>
                            <span>🛞 Подвеска (${hndLvl}/${maxLvl})</span>
                            <b style="color:#fbbf24;">${hndCost !== null ? hndCost.toLocaleString('ru-RU') + ' ₽' : 'MAX'}</b>
                        </button>
                        <button type="button" class="case-open-btn" style="display:flex; justify-content:space-between; padding:8px 10px;" onclick="upgradeGarageCar(${index}, 'nitro')" ${nitCost === null ? 'disabled' : ''}>
                            <span>🔥 Нитро (${nitLvl}/${maxLvl})</span>
                            <b style="color:#fbbf24;">${nitCost !== null ? nitCost.toLocaleString('ru-RU') + ' ₽' : 'MAX'}</b>
                        </button>
                        <button type="button" class="case-open-btn" style="display:flex; justify-content:space-between; padding:8px 10px;" onclick="upgradeGarageCar(${index}, 'economy')" ${ecoCost === null ? 'disabled' : ''}>
                            <span>⛽ Топливная система (${ecoLvl}/${maxLvl})</span>
                            <b style="color:#fbbf24;">${ecoCost !== null ? ecoCost.toLocaleString('ru-RU') + ' ₽' : 'MAX'}</b>
                        </button>
                        ${repCost > 0 ? `<button type="button" class="btn btn-gold" style="margin:4px 0 0 0; padding:8px; font-size:11.5px;" onclick="repairGarageCar(${index})">🔧 Отремонтировать (${repCost.toLocaleString('ru-RU')} ₽)</button>` : ''}
                    </div>
                </div>

                <!-- ВКЛАДКА 3: НОМЕРА -->
                <div class="garage-inspector-panel ${curTab === 'plates' ? '' : 'hidden'}" data-garage-tab-panel="plates">
                    ${plateSlotHtml}
                    <div style="display:flex; flex-direction:column; gap:6px; margin-top:8px;">
                        <button type="button" class="case-open-btn" onclick="toggleGaragePlateView()">🔍 Крупный план 3D-номера на бампере</button>
                        <button type="button" class="case-open-btn" onclick="openSellCarModal(${index})">🏛️ Выставить авто на онлайн-рынок</button>
                    </div>
                </div>

                <!-- ВКЛАДКА 4: СТАЙЛИНГ -->
                <div class="garage-inspector-panel ${curTab === 'styling' ? '' : 'hidden'}" data-garage-tab-panel="styling">
                    <div style="display:flex; flex-direction:column; gap:8px;">
                        <button type="button" class="btn btn-red-cta" style="margin:0; padding:10px 12px; font-size:12.5px;" onclick="openStylingForActiveGarageCar()">🎨 Открыть 3D-ателье стайлинга (Цвет, Винилы, Обвес)</button>
                        <div style="display:grid; grid-template-columns:1fr 1fr; gap:6px;">
                            <button type="button" class="case-open-btn" onclick="cycleGaragePneumo()">💨 Пневмоподвеска</button>
                            <button type="button" class="case-open-btn" onclick="toggleGarageFso()">🚨 Спецсигналы ФСО</button>
                            <button type="button" class="case-open-btn" onclick="cycleGarageEnvironment()">🌦️ Сменить студию</button>
                            <button type="button" class="case-open-btn" onclick="captureGaragePhotoPoster()">📸 3D-Постер</button>
                        </div>
                    </div>
                </div>
            `;
            switchGarageInspectorTab(curTab);
        }
        window.renderGarageActiveCarInspector = renderGarageActiveCarInspector;

        function openActiveCarQuickAction(action) {
            const idx = Math.max(0, Math.min(activeGarageCarIndex || 0, (myCars?.length || 1) - 1));
            if (action === 'plate' || action === 'plates') {
                switchGarageInspectorTab('plates');
                openAttachModal(idx);
                return;
            }
            if (action === 'tuning') {
                switchGarageInspectorTab('tuning');
                const box = document.getElementById('inspector-tuning-box');
                if (box && typeof box.scrollIntoView === 'function') {
                    box.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }
        }
        window.openActiveCarQuickAction = openActiveCarQuickAction;

        function selectGarageCarForPodium(index, fromRender) {
            if (typeof sanitizeNfsMwCarsInGarage === 'function') {
                sanitizeNfsMwCarsInGarage();
            }
            if (!Array.isArray(myCars) || myCars.length === 0) {
                renderGarageCarSidebarList();
                renderGarageActiveCarInspector(0);
                return;
            }
            index = Math.max(0, Math.min(index, myCars.length - 1));
            activeGarageCarIndex = index;

            const car = myCars[index];
            if (!car) return;

            const template = carsData.find(c => c.name === car.name) || {};
            const carCategory = car.category || template.category || 'Автомобиль';

            const titleEl = document.getElementById('garage-3d-car-title');
            const catEl = document.getElementById('garage-3d-car-category');
            const badgeEl = document.getElementById('garage-3d-car-plate-badge');
            if (titleEl) titleEl.textContent = '🏎️ ' + car.name;
            if (catEl) catEl.textContent = carCategory;

            const attachedPlateText = (car.plate && (car.plate.text || car.plate)) ||
                (car.attachedPlate && (car.attachedPlate.text || car.attachedPlate)) ||
                (car.styling && car.styling.plate && car.styling.plate !== 'none' ? car.styling.plate : '');

            if (badgeEl) {
                if (attachedPlateText) {
                    const syn = getCarPlateSynergy(car.name, attachedPlateText);
                    const synBadge = syn
                        ? `<span class="car-synergy-badge" style="font-size:10px;color:#fbbf24;font-weight:800;margin-left:6px;background:rgba(245,158,11,0.18);padding:2px 7px;border-radius:999px;border:1px solid rgba(245,158,11,0.45);">${syn.icon} +${syn.bonusPct}%</span>`
                        : '';
                    badgeEl.innerHTML = `<div class="mini-plate ${getMiniPlateCountryClass(attachedPlateText)}" style="transform:scale(0.95);transform-origin:right center;">${renderMiniPlateInnerHtml(attachedPlateText)}</div><span style="font-size:10px;color:#38bdf8;font-weight:700;margin-left:4px;">🔍 3D бампер</span>${synBadge}`;
                    badgeEl.title = 'Нажмите, чтобы рассмотреть 3D-номер на бампере (Перед / Зад)';
                } else {
                    badgeEl.innerHTML = `<span onclick="event.stopPropagation(); openAttachPlateModal(activeGarageCarIndex)" style="font-size:11px;padding:4px 10px;border-radius:8px;background:rgba(56,189,248,0.12);border:1px solid rgba(56,189,248,0.3);color:#38bdf8;font-weight:700;">🏷️ + Повесить номер</span>`;
                    badgeEl.title = 'Нажмите, чтобы выбрать и повесить госномер на этот автомобиль';
                }
            }

            // Highlight card in #my-cars list and update left sidebar + right inspector
            document.querySelectorAll('.my-car-card').forEach((card, i) => {
                card.classList.toggle('active-podium-card', i === index);
            });
            renderGarageCarSidebarList();
            renderGarageActiveCarInspector(index);

            if (garage3DShowroom) {
                const effectiveStyling = Object.assign({}, car.styling || {}, {
                    plate: attachedPlateText || 'none'
                });
                garage3DShowroom.setCar(car.name, effectiveStyling, () => {
                    updateGarageButtonsState();
                });
                garage3DShowroom.setViewPreset(garageViewMode);
                garage3DShowroom.requestRender();
            }
        }
        window.selectGarageCarForPodium = selectGarageCarForPodium;
        window.selectGarage3DCar = selectGarageCarForPodium;

        function setGarageViewMode(mode) {
            let preset = mode || 'isometric';
            if (preset === '3d') preset = 'isometric';
            garageViewMode = (mode === 'top' || mode === 'side' || mode === 'front' || mode === 'rear' || mode === 'plate_front' || mode === 'plate_rear') ? mode : '3d';

            const btnSide = document.getElementById('btn-gview-side');
            const btnTop = document.getElementById('btn-gview-top');
            const btnFront = document.getElementById('btn-gview-front');
            const btnRear = document.getElementById('btn-gview-rear');
            const btn3D = document.getElementById('btn-gview-3d');
            const btnPlate = document.getElementById('garage-view-plate');

            const isIso = (preset === 'isometric' || mode === '3d');
            const isPlateView = (garageViewMode === 'plate_front' || garageViewMode === 'plate_rear');
            if (btnSide) btnSide.classList.toggle('active', preset === 'side');
            if (btnTop) btnTop.classList.toggle('active', preset === 'top');
            if (btnFront) btnFront.classList.toggle('active', preset === 'front');
            if (btnRear) btnRear.classList.toggle('active', preset === 'rear');
            if (btn3D) btn3D.classList.toggle('active', isIso);
            if (btnPlate) {
                btnPlate.classList.toggle('active', isPlateView);
                btnPlate.textContent = garageViewMode === 'plate_rear' ? '🏷️ Номер (Зад)' : (garageViewMode === 'plate_front' ? '🏷️ Номер (Перед)' : '🏷️ 3D Номер');
            }

            if (garage3DShowroom) {
                garage3DShowroom.setViewPreset(garageViewMode);
                garage3DShowroom.requestRender();
            }
            playTick();
        }
        window.setGarageViewMode = setGarageViewMode;

        function toggleGaragePlateView() {
            const car = Array.isArray(myCars) ? myCars[activeGarageCarIndex] : null;
            const attachedPlateText = car ? ((car.plate && (car.plate.text || car.plate)) || (car.attachedPlate && (car.attachedPlate.text || car.attachedPlate)) || (car.styling && car.styling.plate && car.styling.plate !== 'none' ? car.styling.plate : '')) : '';
            const nextMode = (garageViewMode === 'plate_front') ? 'plate_rear' : 'plate_front';
            setGarageViewMode(nextMode);
            if (!attachedPlateText && typeof openAttachPlateModal === 'function' && typeof event !== 'undefined' && event && event.currentTarget && event.currentTarget.id === 'garage-3d-car-plate-badge') {
                openAttachPlateModal(activeGarageCarIndex);
            }
        }
        window.toggleGaragePlateView = toggleGaragePlateView;

        function resetGarageCamera() {
            if (garage3DShowroom) {
                garage3DShowroom.resetCamera();
            }
            setGarageViewMode('3d');
            playTick();
        }
        window.resetGarageCamera = resetGarageCamera;

        function toggleGarageAutoRotate() {
            if (!garage3DShowroom) return;
            const isRotating = garage3DShowroom.toggleAutoRotate();
            const btn = document.getElementById('btn-gview-autorotate');
            if (btn) btn.classList.toggle('active', isRotating);
            playTick();
        }
        window.toggleGarageAutoRotate = toggleGarageAutoRotate;

        function toggleGarageDoors() {
            if (!garage3DShowroom) return;
            if (!garage3DShowroom.hasCapability('doors')) {
                notifyUser('У этой 3D модели нет открывающихся дверей', 'info');
                return;
            }
            const isOpen = garage3DShowroom.toggleDoors();
            const btn = document.getElementById('btn-gshow-doors');
            if (btn) btn.classList.toggle('active', isOpen);
            playTick();
        }
        window.toggleGarageDoors = toggleGarageDoors;

        function toggleGarageHood() {
            if (!garage3DShowroom) return;
            if (!garage3DShowroom.hasCapability('hood')) {
                notifyUser('У этой 3D модели нет капота', 'info');
                return;
            }
            const isOpen = garage3DShowroom.toggleHood();
            const btn = document.getElementById('btn-gshow-hood');
            if (btn) btn.classList.toggle('active', isOpen);
            playTick();
        }
